## 2. Dependencies (Minimal)

```json
{
  "dependencies": {
    "next": "^15.0.0",
    "react": "^19.0.0",
    "react-dom": "^19.0.0",
    "zustand": "^5.0.0"
  },
  "devDependencies": {
    "typescript": "^5.6.0",
    "@types/react": "^19.0.0",
    "@types/node": "^22.0.0",
    "tailwindcss": "^4.0.0",
    "@tailwindcss/postcss": "^4.0.0",
    "postcss": "^8.0.0",
    "eslint": "^9.0.0",
    "eslint-config-next": "^15.0.0"
  }
}
```

**Why these choices:**
- **zustand** -- Lightweight state management (under 1KB). Perfect for managing transport state, pattern data, and settings across components without prop drilling. No providers needed, works outside React components (important for the audio scheduler callback).
- **No Tone.js** -- The Web Audio API is sufficient for drum synthesis and avoids a 150KB+ dependency. We generate all sounds programmatically.
- **No additional UI libraries** -- Tailwind CSS handles all styling. Custom components for knobs/sliders keep the bundle small.

---

## 3. Data Models

### 3.1 Core Types (`/src/lib/patterns/types.ts`)

```typescript
// The fundamental instrument types
export type InstrumentId =
  | 'kick'
  | 'snare'
  | 'hihat-closed'
  | 'hihat-open'
  | 'tom-high'
  | 'tom-mid'
  | 'tom-low'
  | 'crash'
  | 'ride';

// A single step in the sequencer grid
export interface Step {
  active: boolean;       // Is this step triggered?
  velocity: number;      // 0.0 - 1.0 (default 0.8)
  accent: boolean;       // Accented hit (plays louder)
}

// One instrument's track across all steps
export interface Track {
  instrumentId: InstrumentId;
  label: string;         // Display name, e.g. "Kick"
  steps: Step[];         // Length matches pattern.totalSteps
  muted: boolean;
  volume: number;        // 0.0 - 1.0
}

// Subdivision options
export type Subdivision = '8th' | '16th' | 'triplet';

// Time signature
export interface TimeSignature {
  beats: number;         // Numerator (e.g., 4, 3, 6)
  noteValue: number;     // Denominator (e.g., 4, 8)
}

// A complete drum pattern
export interface DrumPattern {
  id: string;
  name: string;
  description: string;
  category: PatternCategory;
  timeSignature: TimeSignature;
  subdivision: Subdivision;
  defaultBpm: number;
  totalSteps: number;    // Derived: beats * subdivisionMultiplier
  tracks: Track[];
  tags: string[];
}

export type PatternCategory =
  | 'rock'
  | 'funk'
  | 'latin'
  | 'jazz'
  | 'rudiment'
  | 'custom';

// For rudiments that use hand notation (R/L)
export type Hand = 'R' | 'L';

export interface RudimentPattern extends DrumPattern {
  sticking: Hand[];      // R/L pattern per step
}
```

