### 4.2 AudioEngine.ts -- Singleton Pattern

```typescript
// Conceptual structure (not exhaustive)
class AudioEngine {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;
  private compressor: DynamicsCompressorNode | null = null;

  // Lazy initialization (AudioContext must be created after user gesture)
  init(): AudioContext {
    if (!this.ctx) {
      this.ctx = new AudioContext();
      this.compressor = this.ctx.createDynamicsCompressor();
      this.masterGain = this.ctx.createGain();
      this.masterGain.connect(this.compressor);
      this.compressor.connect(this.ctx.destination);
    }
    // Resume if suspended (browser autoplay policy)
    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
    return this.ctx;
  }

  get currentTime(): number {
    return this.ctx?.currentTime ?? 0;
  }

  get destination(): GainNode {
    return this.masterGain!;
  }

  setMasterVolume(value: number): void {
    if (this.masterGain) {
      this.masterGain.gain.setValueAtTime(value, this.ctx!.currentTime);
    }
  }
}

export const audioEngine = new AudioEngine(); // Singleton
```

### 4.3 DrumSynth.ts -- Sound Synthesis

Each function creates short-lived Web Audio nodes at the scheduled time, routed through a per-instrument gain node to the master output. Nodes are garbage collected after their envelopes complete.

**Kick drum** -- Based on the approach from [Sonoport's synthesis tutorial](https://sonoport.github.io/synthesising-sounds-webaudio.html):
```typescript
function playKick(ctx: AudioContext, destination: AudioNode, time: number, velocity: number) {
  // Oscillator 1: Triangle wave, 150Hz -> 0.001Hz exponential sweep
  const osc = ctx.createOscillator();
  osc.type = 'triangle';
  osc.frequency.setValueAtTime(150, time);
  osc.frequency.exponentialRampToValueAtTime(0.001, time + 0.5);

  // Gain envelope: sharp attack, 0.5s decay
  const gainNode = ctx.createGain();
  gainNode.gain.setValueAtTime(velocity, time);
  gainNode.gain.exponentialRampToValueAtTime(0.001, time + 0.5);

  // Oscillator 2: Sine "body" at lower frequency
  const osc2 = ctx.createOscillator();
  osc2.type = 'sine';
  osc2.frequency.setValueAtTime(80, time);
  osc2.frequency.exponentialRampToValueAtTime(0.001, time + 0.5);

  const gainNode2 = ctx.createGain();
  gainNode2.gain.setValueAtTime(velocity * 0.7, time);
  gainNode2.gain.exponentialRampToValueAtTime(0.001, time + 0.5);

  osc.connect(gainNode).connect(destination);
  osc2.connect(gainNode2).connect(destination);

  osc.start(time);
  osc.stop(time + 0.5);
  osc2.start(time);
  osc2.stop(time + 0.5);
}
```

**Snare** -- Noise burst plus pitched tones, based on the [cofx.nl synthesis approach](https://blog.cofx.nl/browser-beats-snare-and-hi-hat.html):
```typescript
function playSnare(ctx: AudioContext, destination: AudioNode, time: number, velocity: number) {
  // --- Noise component (the "rattle" of the snare wires) ---
  const bufferSize = ctx.sampleRate * 0.2; // 200ms of noise
  const noiseBuffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
  const output = noiseBuffer.getChannelData(0);
  for (let i = 0; i < bufferSize; i++) {
    output[i] = Math.random() * 2 - 1;
  }

  const noise = ctx.createBufferSource();
  noise.buffer = noiseBuffer;

  const noiseFilter = ctx.createBiquadFilter();
  noiseFilter.type = 'highpass';
  noiseFilter.frequency.setValueAtTime(1000, time);

  const noiseGain = ctx.createGain();
  noiseGain.gain.setValueAtTime(velocity * 0.7, time);
  noiseGain.gain.exponentialRampToValueAtTime(0.001, time + 0.2);

  noise.connect(noiseFilter).connect(noiseGain).connect(destination);
  noise.start(time);
  noise.stop(time + 0.2);

  // --- Pitched component (drum body) ---
  const osc = ctx.createOscillator();
  osc.type = 'triangle';
  osc.frequency.setValueAtTime(185, time);

  const oscGain = ctx.createGain();
  oscGain.gain.setValueAtTime(velocity * 0.5, time);
  oscGain.gain.exponentialRampToValueAtTime(0.001, time + 0.1);

  osc.connect(oscGain).connect(destination);
  osc.start(time);
  osc.stop(time + 0.1);
}
```

**Hi-hat (closed/open)** -- Based on [Joe Sullivan's hi-hat synthesis](http://joesul.li/van/synthesizing-hi-hats/) using the 6-square-wave-ratios technique from the [Sonoport article](https://sonoport.github.io/synthesising-sounds-webaudio.html):
```typescript
function playHiHat(
  ctx: AudioContext, destination: AudioNode,
  time: number, velocity: number, open: boolean
) {
  const fundamental = 40;
  const ratios = [2, 3, 4.16, 5.43, 6.79, 8.21];
  const decayTime = open ? 0.3 : 0.08;

  // Bandpass filter for metallic tone
  const bandpass = ctx.createBiquadFilter();
  bandpass.type = 'bandpass';
  bandpass.frequency.setValueAtTime(10000, time);

  // Highpass to remove low-end rumble
  const highpass = ctx.createBiquadFilter();
  highpass.type = 'highpass';
  highpass.frequency.setValueAtTime(7000, time);

  const gainNode = ctx.createGain();
  gainNode.gain.setValueAtTime(velocity * 0.3, time);
  gainNode.gain.exponentialRampToValueAtTime(0.001, time + decayTime);

  bandpass.connect(highpass).connect(gainNode).connect(destination);

  // Six square-wave oscillators at harmonic ratios
  ratios.forEach((ratio) => {
    const osc = ctx.createOscillator();
    osc.type = 'square';
    osc.frequency.setValueAtTime(fundamental * ratio, time);
    osc.connect(bandpass);
    osc.start(time);
    osc.stop(time + decayTime);
  });
}
```

**Tom** -- Similar to kick but with adjustable pitch for high/mid/low:
```typescript
function playTom(
  ctx: AudioContext, destination: AudioNode,
  time: number, velocity: number, pitch: 'high' | 'mid' | 'low'
) {
  const freqMap = { high: 200, mid: 150, low: 100 };
  const freq = freqMap[pitch];

  const osc = ctx.createOscillator();
  osc.type = 'sine';
  osc.frequency.setValueAtTime(freq, time);
  osc.frequency.exponentialRampToValueAtTime(freq * 0.5, time + 0.3);

  const gain = ctx.createGain();
  gain.gain.setValueAtTime(velocity, time);
  gain.gain.exponentialRampToValueAtTime(0.001, time + 0.3);

  osc.connect(gain).connect(destination);
  osc.start(time);
  osc.stop(time + 0.3);
}
```

**Crash/Ride** -- Filtered noise with long/medium decay:
```typescript
function playCymbal(
  ctx: AudioContext, destination: AudioNode,
  time: number, velocity: number, type: 'crash' | 'ride'
) {
  const decayTime = type === 'crash' ? 1.5 : 0.6;
  const filterFreq = type === 'crash' ? 5000 : 8000;

  // White noise
  const bufferSize = ctx.sampleRate * decayTime;
  const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
  const data = buffer.getChannelData(0);
  for (let i = 0; i < bufferSize; i++) {
    data[i] = Math.random() * 2 - 1;
  }

  const source = ctx.createBufferSource();
  source.buffer = buffer;

  const highpass = ctx.createBiquadFilter();
  highpass.type = 'highpass';
  highpass.frequency.setValueAtTime(filterFreq, time);

  const gain = ctx.createGain();
  gain.gain.setValueAtTime(velocity * 0.4, time);
  gain.gain.exponentialRampToValueAtTime(0.001, time + decayTime);

  source.connect(highpass).connect(gain).connect(destination);
  source.start(time);
  source.stop(time + decayTime);
}
```

### 4.4 Scheduler.ts -- The Timing Brain

This implements the [proven "two clocks" pattern](https://web.dev/articles/audio-scheduling) from Chris Wilson's metronome demo.

```typescript
// Conceptual structure
class Scheduler {
  private timerId: number | null = null;
  private nextStepTime: number = 0;
  private currentStep: number = 0;

  // Tuning parameters
  private readonly LOOKAHEAD_MS = 25;        // setTimeout interval
  private readonly SCHEDULE_AHEAD_S = 0.1;   // How far ahead to schedule (100ms)

  private onStep: ((step: number, time: number) => void) | null = null;

  start(bpm: number, totalSteps: number, onStep: callback) {
    this.onStep = onStep;
    this.currentStep = 0;
    this.nextStepTime = audioEngine.currentTime;
    this.schedule(bpm, totalSteps);
  }

  private schedule(bpm: number, totalSteps: number) {
    const secondsPerStep = this.calculateStepDuration(bpm, subdivision);

    while (this.nextStepTime < audioEngine.currentTime + this.SCHEDULE_AHEAD_S) {
      // Apply swing to even-numbered steps
      let swingOffset = 0;
      if (this.currentStep % 2 === 1 && swing > 0) {
        swingOffset = secondsPerStep * swing * 0.33;
      }

      this.onStep?.(this.currentStep, this.nextStepTime + swingOffset);

      this.nextStepTime += secondsPerStep;
      this.currentStep = (this.currentStep + 1) % totalSteps;
    }

    this.timerId = window.setTimeout(
      () => this.schedule(bpm, totalSteps),
      this.LOOKAHEAD_MS
    );
  }

  stop() {
    if (this.timerId !== null) {
      clearTimeout(this.timerId);
      this.timerId = null;
    }
  }
}
```

The key insight: `setTimeout` fires every ~25ms on the JavaScript thread (imprecise, but fine). Inside that callback, we look at what notes need to play in the next 100ms window and schedule them via the Web Audio clock (precise to the hardware sample). This decoupling is what gives us rock-solid timing regardless of UI rendering or JavaScript garbage collection pauses.

