export type InstrumentId =
  | 'kick'
  | 'snare'
  | 'hihat-closed'
  | 'hihat-open'
  | 'tom-high'
  | 'tom-mid'
  | 'tom-low'
  | 'crash'
  | 'ride';

export interface Step {
  active: boolean;
  velocity: number; // 0.0 - 1.0
  accent: boolean;
}

export interface Track {
  instrumentId: InstrumentId;
  label: string;
  steps: Step[];
  muted: boolean;
  volume: number; // 0.0 - 1.0
}

export type Subdivision = '8th' | '16th' | 'triplet';

export interface TimeSignature {
  beats: number;
  noteValue: number;
}

export type PatternCategory = 'rock' | 'funk' | 'latin' | 'world' | 'rudiment';

export type Hand = 'R' | 'L';

export interface DrumPattern {
  id: string;
  name: string;
  description: string;
  category: PatternCategory;
  timeSignature: TimeSignature;
  subdivision: Subdivision;
  defaultBpm: number;
  totalSteps: number;
  tracks: Track[];
  tags: string[];
  sticking?: Hand[];
}

export type PlayState = 'stopped' | 'playing' | 'paused';

export type PracticeMode = 'loop' | 'tempo-ramp';

export interface TempoRampConfig {
  startBpm: number;
  endBpm: number;
  incrementBpm: number;
  barsPerIncrement: number;
}

import { Step, DrumPattern } from './types';

export function boolsToSteps(bools: (0 | 1)[], defaultVelocity = 0.8): Step[] {
  return bools.map((b) => ({
    active: b === 1,
    velocity: defaultVelocity,
    accent: false,
  }));
}

export function accentedSteps(
  bools: (0 | 1)[],
  accents: (0 | 1)[],
  baseVelocity = 0.6,
  accentVelocity = 1.0
): Step[] {
  return bools.map((b, i) => ({
    active: b === 1,
    velocity: accents[i] ? accentVelocity : baseVelocity,
    accent: accents[i] === 1,
  }));
}

export function clonePattern(pattern: DrumPattern): DrumPattern {
  return JSON.parse(JSON.stringify(pattern));
}

