import { InstrumentId } from '../patterns/types';
import { audioEngine } from './AudioEngine';

export function playInstrument(
  instrumentId: InstrumentId,
  time: number,
  velocity: number,
  volume: number
): void {
  const ctx = audioEngine.context;
  if (!ctx) return;

  const dest = audioEngine.destination;
  const vol = velocity * volume;

  switch (instrumentId) {
    case 'kick':
      playKick(ctx, dest, time, vol);
      break;
    case 'snare':
      playSnare(ctx, dest, time, vol);
      break;
    case 'hihat-closed':
      playHiHat(ctx, dest, time, vol, false);
      break;
    case 'hihat-open':
      playHiHat(ctx, dest, time, vol, true);
      break;
    case 'tom-high':
      playTom(ctx, dest, time, vol, 'high');
      break;
    case 'tom-mid':
      playTom(ctx, dest, time, vol, 'mid');
      break;
    case 'tom-low':
      playTom(ctx, dest, time, vol, 'low');
      break;
    case 'crash':
      playCymbal(ctx, dest, time, vol, 'crash');
      break;
    case 'ride':
      playCymbal(ctx, dest, time, vol, 'ride');
      break;
  }
}

function playKick(
  ctx: AudioContext,
  destination: AudioNode,
  time: number,
  velocity: number
): void {
  // Triangle oscillator with pitch sweep for the "click"
  const osc = ctx.createOscillator();
  osc.type = 'triangle';
  osc.frequency.setValueAtTime(150, time);
  osc.frequency.exponentialRampToValueAtTime(0.01, time + 0.5);

  const gainNode = ctx.createGain();
  gainNode.gain.setValueAtTime(velocity, time);
  gainNode.gain.exponentialRampToValueAtTime(0.001, time + 0.5);

  // Sine "body" at lower frequency
  const osc2 = ctx.createOscillator();
  osc2.type = 'sine';
  osc2.frequency.setValueAtTime(80, time);
  osc2.frequency.exponentialRampToValueAtTime(0.01, time + 0.5);

  const gainNode2 = ctx.createGain();
  gainNode2.gain.setValueAtTime(velocity * 0.7, time);
  gainNode2.gain.exponentialRampToValueAtTime(0.001, time + 0.5);

  osc.connect(gainNode).connect(destination);
  osc2.connect(gainNode2).connect(destination);

  osc.start(time);
  osc.stop(time + 0.5);
  osc2.start(time);
  osc2.stop(time + 0.5);
}

function playSnare(
  ctx: AudioContext,
  destination: AudioNode,
  time: number,
  velocity: number
): void {
  // Noise component (snare wires)
  const noiseBuffer = audioEngine.noiseBuffer;
  if (noiseBuffer) {
    const noise = ctx.createBufferSource();
    noise.buffer = noiseBuffer;

    const noiseFilter = ctx.createBiquadFilter();
    noiseFilter.type = 'highpass';
    noiseFilter.frequency.setValueAtTime(1000, time);

    const noiseGain = ctx.createGain();
    noiseGain.gain.setValueAtTime(velocity * 0.7, time);
    noiseGain.gain.exponentialRampToValueAtTime(0.001, time + 0.2);

    noise.connect(noiseFilter).connect(noiseGain).connect(destination);
    noise.start(time);
    noise.stop(time + 0.2);
  }

  // Body tone
  const osc = ctx.createOscillator();
  osc.type = 'triangle';
  osc.frequency.setValueAtTime(185, time);

  const oscGain = ctx.createGain();
  oscGain.gain.setValueAtTime(velocity * 0.5, time);
  oscGain.gain.exponentialRampToValueAtTime(0.001, time + 0.1);

  osc.connect(oscGain).connect(destination);
  osc.start(time);
  osc.stop(time + 0.1);
}

function playHiHat(
  ctx: AudioContext,
  destination: AudioNode,
  time: number,
  velocity: number,
  open: boolean
): void {
  const fundamental = 40;
  const ratios = [2, 3, 4.16, 5.43, 6.79, 8.21];
  const decayTime = open ? 0.3 : 0.08;

  const bandpass = ctx.createBiquadFilter();
  bandpass.type = 'bandpass';
  bandpass.frequency.setValueAtTime(10000, time);

  const highpass = ctx.createBiquadFilter();
  highpass.type = 'highpass';
  highpass.frequency.setValueAtTime(7000, time);

  const gainNode = ctx.createGain();
  gainNode.gain.setValueAtTime(velocity * 0.3, time);
  gainNode.gain.exponentialRampToValueAtTime(0.001, time + decayTime);

  bandpass.connect(highpass).connect(gainNode).connect(destination);

  ratios.forEach((ratio) => {
    const osc = ctx.createOscillator();
    osc.type = 'square';
    osc.frequency.setValueAtTime(fundamental * ratio, time);
    osc.connect(bandpass);
    osc.start(time);
    osc.stop(time + decayTime);
  });
}

function playTom(
  ctx: AudioContext,
  destination: AudioNode,
  time: number,
  velocity: number,
  pitch: 'high' | 'mid' | 'low'
): void {
  const freqMap = { high: 200, mid: 150, low: 100 };
  const freq = freqMap[pitch];

  const osc = ctx.createOscillator();
  osc.type = 'sine';
  osc.frequency.setValueAtTime(freq, time);
  osc.frequency.exponentialRampToValueAtTime(freq * 0.5, time + 0.3);

  const gain = ctx.createGain();
  gain.gain.setValueAtTime(velocity, time);
  gain.gain.exponentialRampToValueAtTime(0.001, time + 0.3);

  osc.connect(gain).connect(destination);
  osc.start(time);
  osc.stop(time + 0.3);
}

function playCymbal(
  ctx: AudioContext,
  destination: AudioNode,
  time: number,
  velocity: number,
  type: 'crash' | 'ride'
): void {
  const decayTime = type === 'crash' ? 1.5 : 0.6;
  const filterFreq = type === 'crash' ? 5000 : 8000;

  const noiseBuffer = audioEngine.noiseBuffer;
  if (!noiseBuffer) return;

  const source = ctx.createBufferSource();
  source.buffer = noiseBuffer;

  const highpass = ctx.createBiquadFilter();
  highpass.type = 'highpass';
  highpass.frequency.setValueAtTime(filterFreq, time);

  const gain = ctx.createGain();
  gain.gain.setValueAtTime(velocity * 0.4, time);
  gain.gain.exponentialRampToValueAtTime(0.001, time + decayTime);

  source.connect(highpass).connect(gain).connect(destination);
  source.start(time);
  source.stop(time + decayTime);
}

import { audioEngine } from './AudioEngine';

export type StepCallback = (step: number, time: number) => void;

export class Scheduler {
  private timerId: ReturnType<typeof setTimeout> | null = null;
  private nextStepTime = 0;
  private currentStep = 0;
  private onStep: StepCallback | null = null;
  private totalSteps = 8;
  private bpm = 120;
  private swing = 0;
  private subdivision: '8th' | '16th' | 'triplet' = '8th';
  private stepsPerBar = 8;
  private barsPlayed = 0;
  private stepsInCurrentBar = 0;

  // Callbacks for practice mode
  private onBarComplete: ((barCount: number) => void) | null = null;

  private readonly LOOKAHEAD_MS = 25;
  private readonly SCHEDULE_AHEAD_S = 0.1;

  start(
    bpm: number,
    totalSteps: number,
    subdivision: '8th' | '16th' | 'triplet',
    swing: number,
    onStep: StepCallback,
    onBarComplete?: (barCount: number) => void
  ): void {
    this.bpm = bpm;
    this.totalSteps = totalSteps;
    this.subdivision = subdivision;
    this.swing = swing;
    this.onStep = onStep;
    this.onBarComplete = onBarComplete ?? null;
    this.currentStep = 0;
    this.barsPlayed = 0;
    this.stepsInCurrentBar = 0;
    this.stepsPerBar = totalSteps;

    audioEngine.init();
    this.nextStepTime = audioEngine.currentTime + 0.05; // small lead time
    this.schedule();
  }

  stop(): void {
    if (this.timerId !== null) {
      clearTimeout(this.timerId);
      this.timerId = null;
    }
    this.onStep = null;
    this.onBarComplete = null;
  }

  setBpm(bpm: number): void {
    this.bpm = bpm;
  }

  setSwing(swing: number): void {
    this.swing = swing;
  }

  get step(): number {
    return this.currentStep;
  }

  get bars(): number {
    return this.barsPlayed;
  }

  private getStepDuration(): number {
    const beatsPerSecond = this.bpm / 60;
    switch (this.subdivision) {
      case '8th':
        return 1 / (beatsPerSecond * 2);
      case '16th':
        return 1 / (beatsPerSecond * 4);
      case 'triplet':
        return 1 / (beatsPerSecond * 3);
    }
  }

  private schedule(): void {
    const stepDuration = this.getStepDuration();

    while (this.nextStepTime < audioEngine.currentTime + this.SCHEDULE_AHEAD_S) {
      // Apply swing to even-numbered off-beat steps
      let swingOffset = 0;
      if (this.currentStep % 2 === 1 && this.swing > 0) {
        swingOffset = stepDuration * this.swing * 0.33;
      }

      const scheduledTime = this.nextStepTime + swingOffset;
      this.onStep?.(this.currentStep, scheduledTime);

      // Track bar progress
      this.stepsInCurrentBar++;
      if (this.stepsInCurrentBar >= this.stepsPerBar) {
        this.stepsInCurrentBar = 0;
        this.barsPlayed++;
        this.onBarComplete?.(this.barsPlayed);
      }

      this.nextStepTime += stepDuration;
      this.currentStep = (this.currentStep + 1) % this.totalSteps;
    }

    this.timerId = setTimeout(() => this.schedule(), this.LOOKAHEAD_MS);
  }
}

