import { create } from 'zustand';
import { PlayState } from '../patterns/types';
import { Scheduler } from '../audio/Scheduler';
import { playInstrument } from '../audio/DrumSynth';
import { audioEngine } from '../audio/AudioEngine';

const scheduler = new Scheduler();

interface TransportStore {
  playState: PlayState;
  bpm: number;
  currentStep: number;
  swing: number;

  play: () => void;
  pause: () => void;
  stop: () => void;
  setBpm: (bpm: number) => void;
  setCurrentStep: (step: number) => void;
  setSwing: (swing: number) => void;
}

export const useTransportStore = create<TransportStore>((set, get) => ({
  playState: 'stopped',
  bpm: 100,
  currentStep: -1,
  swing: 0,

  play: () => {
    const { usePatternStore } = require('./usePatternStore');
    const pattern = usePatternStore.getState().currentPattern;
    const { bpm, swing } = get();

    audioEngine.init();

    const onStep = (step: number, time: number) => {
      // Play sounds for active tracks at this step
      pattern.tracks.forEach((track) => {
        if (track.muted) return;
        const s = track.steps[step];
        if (s && s.active) {
          playInstrument(track.instrumentId, time, s.velocity, track.volume);
        }
      });

      // Schedule UI update synced to audio time
      const delayMs = Math.max(0, (time - audioEngine.currentTime) * 1000);
      setTimeout(() => {
        set({ currentStep: step });
      }, delayMs);
    };

    const { usePracticeStore } = require('./usePracticeStore');
    const practiceStore = usePracticeStore.getState();
    const onBarComplete = practiceStore.mode === 'tempo-ramp'
      ? (barCount: number) => {
          const ps = usePracticeStore.getState();
          if (ps.mode === 'tempo-ramp' && ps.tempoRampConfig) {
            const config = ps.tempoRampConfig;
            if (barCount > 0 && barCount % config.barsPerIncrement === 0) {
              const currentBpm = get().bpm;
              const newBpm = Math.min(currentBpm + config.incrementBpm, config.endBpm);
              if (newBpm !== currentBpm) {
                set({ bpm: newBpm });
                scheduler.setBpm(newBpm);
                usePracticeStore.setState({ currentBpm: newBpm });
              }
            }
          }
          usePracticeStore.setState({ barsPlayed: barCount });
        }
      : undefined;

    scheduler.start(bpm, pattern.totalSteps, pattern.subdivision, swing, onStep, onBarComplete);
    set({ playState: 'playing' });
  },

  pause: () => {
    scheduler.stop();
    set({ playState: 'paused' });
  },

  stop: () => {
    scheduler.stop();
    set({ playState: 'stopped', currentStep: -1 });
  },

  setBpm: (bpm: number) => {
    const clamped = Math.max(40, Math.min(240, bpm));
    set({ bpm: clamped });
    scheduler.setBpm(clamped);
  },

  setCurrentStep: (step: number) => set({ currentStep: step }),

  setSwing: (swing: number) => {
    set({ swing });
    scheduler.setSwing(swing);
  },
}));

import { create } from 'zustand';
import { DrumPattern } from '../patterns/types';
import { basicRockBeat } from '../patterns/rock';
import { clonePattern } from '../patterns/utils';

interface PatternStore {
  currentPattern: DrumPattern;
  isModified: boolean;

  loadPattern: (pattern: DrumPattern) => void;
  toggleStep: (trackIndex: number, stepIndex: number) => void;
  setTrackVolume: (trackIndex: number, volume: number) => void;
  toggleTrackMute: (trackIndex: number) => void;
  resetPattern: () => void;
}

export const usePatternStore = create<PatternStore>((set, get) => ({
  currentPattern: clonePattern(basicRockBeat),
  isModified: false,

  loadPattern: (pattern: DrumPattern) => {
    set({ currentPattern: clonePattern(pattern), isModified: false });
  },

  toggleStep: (trackIndex: number, stepIndex: number) => {
    const pattern = clonePattern(get().currentPattern);
    const step = pattern.tracks[trackIndex].steps[stepIndex];
    step.active = !step.active;
    set({ currentPattern: pattern, isModified: true });
  },

  setTrackVolume: (trackIndex: number, volume: number) => {
    const pattern = clonePattern(get().currentPattern);
    pattern.tracks[trackIndex].volume = volume;
    set({ currentPattern: pattern });
  },

  toggleTrackMute: (trackIndex: number) => {
    const pattern = clonePattern(get().currentPattern);
    pattern.tracks[trackIndex].muted = !pattern.tracks[trackIndex].muted;
    set({ currentPattern: pattern });
  },

  resetPattern: () => {
    const { allPatterns } = require('../patterns');
    const original = allPatterns.find(
      (p: DrumPattern) => p.id === get().currentPattern.id
    );
    if (original) {
      set({ currentPattern: clonePattern(original), isModified: false });
    }
  },
}));

import { create } from 'zustand';
import { persist } from 'zustand/middleware';

interface SettingsStore {
  masterVolume: number;
  lastPatternId: string | null;
