'use client';

import React from 'react';
import { InstrumentId } from '@/lib/patterns/types';

const instrumentColors: Record<InstrumentId, string> = {
  'kick': 'bg-red-500',
  'snare': 'bg-yellow-400',
  'hihat-closed': 'bg-cyan-400',
  'hihat-open': 'bg-cyan-300',
  'tom-high': 'bg-purple-400',
  'tom-mid': 'bg-purple-500',
  'tom-low': 'bg-purple-600',
  'crash': 'bg-orange-400',
  'ride': 'bg-green-400',
};

interface BeatCellProps {
  active: boolean;
  accent: boolean;
  isCurrent: boolean;
  isDownbeat: boolean;
  instrumentId: InstrumentId;
  onClick: () => void;
}

export const BeatCell = React.memo(function BeatCell({
  active,
  accent,
  isCurrent,
  isDownbeat,
  instrumentId,
  onClick,
}: BeatCellProps) {
  const color = instrumentColors[instrumentId];

  return (
    <button
      onClick={onClick}
      className={`
        w-9 h-9 sm:w-10 sm:h-10 rounded-md border transition-all duration-75 cursor-pointer
        ${isDownbeat ? 'border-gray-600' : 'border-gray-700/50'}
        ${isCurrent ? 'ring-2 ring-white/80 scale-105' : ''}
        ${active
          ? `${color} ${accent ? 'brightness-125 shadow-lg' : 'opacity-80'}`
          : isDownbeat
            ? 'bg-gray-800/80'
            : 'bg-gray-800/40'
        }
        hover:brightness-125 active:scale-95
      `}
      aria-label={`${active ? 'Disable' : 'Enable'} step`}
    />
  );
});

'use client';

import React from 'react';
import { Track } from '@/lib/patterns/types';
import { BeatCell } from './BeatCell';

interface TrackRowProps {
  track: Track;
  trackIndex: number;
  currentStep: number;
  stepsPerBeat: number;
  onToggleStep: (trackIndex: number, stepIndex: number) => void;
  onToggleMute: (trackIndex: number) => void;
}

export const TrackRow = React.memo(function TrackRow({
  track,
  trackIndex,
  currentStep,
  stepsPerBeat,
  onToggleStep,
  onToggleMute,
}: TrackRowProps) {
  return (
    <div className="flex items-center gap-2">
      <button
        onClick={() => onToggleMute(trackIndex)}
        className={`
          w-20 sm:w-24 text-xs sm:text-sm font-medium text-left truncate px-2 py-1 rounded cursor-pointer
          ${track.muted ? 'text-gray-600 line-through' : 'text-gray-200'}
          hover:bg-gray-700/50 transition-colors
        `}
      >
        {track.label}
      </button>
      <div className="flex gap-0.5 sm:gap-1">
        {track.steps.map((step, stepIndex) => {
          const isDownbeat = stepIndex % stepsPerBeat === 0;
          return (
            <BeatCell
              key={stepIndex}
              active={step.active}
              accent={step.accent}
              isCurrent={currentStep === stepIndex}
              isDownbeat={isDownbeat}
              instrumentId={track.instrumentId}
              onClick={() => onToggleStep(trackIndex, stepIndex)}
            />
          );
