 1→class AudioEngine {
 2→  private ctx: AudioContext | null = null;
 3→  private masterGain: GainNode | null = null;
 4→  private compressor: DynamicsCompressorNode | null = null;
 5→  private _noiseBuffer: AudioBuffer | null = null;
 6→
 7→  init(): AudioContext {
 8→    if (!this.ctx) {
 9→      this.ctx = new AudioContext();
10→      this.compressor = this.ctx.createDynamicsCompressor();
11→      this.compressor.threshold.value = -12;
12→      this.compressor.knee.value = 10;
13→      this.compressor.ratio.value = 4;
14→      this.masterGain = this.ctx.createGain();
15→      this.masterGain.connect(this.compressor);
16→      this.compressor.connect(this.ctx.destination);
17→
18→      // Pre-generate noise buffer (2 seconds)
19→      const bufferSize = this.ctx.sampleRate * 2;
20→      this._noiseBuffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
21→      const data = this._noiseBuffer.getChannelData(0);
22→      for (let i = 0; i < bufferSize; i++) {
23→        data[i] = Math.random() * 2 - 1;
24→      }
25→    }
26→
27→    if (this.ctx.state === 'suspended') {
28→      this.ctx.resume();
29→    }
30→    return this.ctx;
31→  }
32→
33→  get context(): AudioContext | null {
34→    return this.ctx;
35→  }
36→
37→  get currentTime(): number {
38→    return this.ctx?.currentTime ?? 0;
39→  }
40→
41→  get destination(): GainNode {
42→    return this.masterGain!;
43→  }
44→
45→  get noiseBuffer(): AudioBuffer | null {
46→    return this._noiseBuffer;
47→  }
48→
49→  setMasterVolume(value: number): void {
50→    if (this.masterGain && this.ctx) {
51→      this.masterGain.gain.setValueAtTime(value, this.ctx.currentTime);
52→    }
53→  }
54→}
55→
56→export const audioEngine = new AudioEngine();
57→

  1→import { InstrumentId } from '../patterns/types';
  2→import { audioEngine } from './AudioEngine';
  3→
  4→export function playInstrument(
  5→  instrumentId: InstrumentId,
  6→  time: number,
  7→  velocity: number,
  8→  volume: number
  9→): void {
 10→  const ctx = audioEngine.context;
 11→  if (!ctx) return;
 12→
 13→  const dest = audioEngine.destination;
 14→  const vol = velocity * volume;
 15→
 16→  switch (instrumentId) {
 17→    case 'kick':
 18→      playKick(ctx, dest, time, vol);
 19→      break;
 20→    case 'snare':
 21→      playSnare(ctx, dest, time, vol);
 22→      break;
 23→    case 'hihat-closed':
 24→      playHiHat(ctx, dest, time, vol, false);
 25→      break;
 26→    case 'hihat-open':
 27→      playHiHat(ctx, dest, time, vol, true);
 28→      break;
 29→    case 'tom-high':
 30→      playTom(ctx, dest, time, vol, 'high');
 31→      break;
 32→    case 'tom-mid':
 33→      playTom(ctx, dest, time, vol, 'mid');
 34→      break;
 35→    case 'tom-low':
 36→      playTom(ctx, dest, time, vol, 'low');
 37→      break;
 38→    case 'crash':
 39→      playCymbal(ctx, dest, time, vol, 'crash');
 40→      break;
 41→    case 'ride':
 42→      playCymbal(ctx, dest, time, vol, 'ride');
 43→      break;
 44→  }
 45→}
 46→
 47→function playKick(
 48→  ctx: AudioContext,
 49→  destination: AudioNode,
 50→  time: number,
 51→  velocity: number
 52→): void {
 53→  // Triangle oscillator with pitch sweep for the "click"
 54→  const osc = ctx.createOscillator();
 55→  osc.type = 'triangle';
 56→  osc.frequency.setValueAtTime(150, time);
 57→  osc.frequency.exponentialRampToValueAtTime(0.01, time + 0.5);
 58→
 59→  const gainNode = ctx.createGain();
 60→  gainNode.gain.setValueAtTime(velocity, time);
 61→  gainNode.gain.exponentialRampToValueAtTime(0.001, time + 0.5);
 62→
 63→  // Sine "body" at lower frequency
 64→  const osc2 = ctx.createOscillator();
 65→  osc2.type = 'sine';
 66→  osc2.frequency.setValueAtTime(80, time);
 67→  osc2.frequency.exponentialRampToValueAtTime(0.01, time + 0.5);
 68→
 69→  const gainNode2 = ctx.createGain();
 70→  gainNode2.gain.setValueAtTime(velocity * 0.7, time);
 71→  gainNode2.gain.exponentialRampToValueAtTime(0.001, time + 0.5);
 72→
 73→  osc.connect(gainNode).connect(destination);
 74→  osc2.connect(gainNode2).connect(destination);
 75→
 76→  osc.start(time);
 77→  osc.stop(time + 0.5);
 78→  osc2.start(time);
 79→  osc2.stop(time + 0.5);
 80→}
 81→
 82→function playSnare(
 83→  ctx: AudioContext,
 84→  destination: AudioNode,
 85→  time: number,
 86→  velocity: number
 87→): void {
 88→  // Noise component (snare wires)
 89→  const noiseBuffer = audioEngine.noiseBuffer;
 90→  if (noiseBuffer) {
 91→    const noise = ctx.createBufferSource();
 92→    noise.buffer = noiseBuffer;
 93→
 94→    const noiseFilter = ctx.createBiquadFilter();
 95→    noiseFilter.type = 'highpass';
 96→    noiseFilter.frequency.setValueAtTime(1000, time);
 97→
 98→    const noiseGain = ctx.createGain();
 99→    noiseGain.gain.setValueAtTime(velocity * 0.7, time);
100→    noiseGain.gain.exponentialRampToValueAtTime(0.001, time + 0.2);
101→
102→    noise.connect(noiseFilter).connect(noiseGain).connect(destination);
103→    noise.start(time);
104→    noise.stop(time + 0.2);
105→  }
106→
107→  // Body tone
108→  const osc = ctx.createOscillator();
109→  osc.type = 'triangle';
110→  osc.frequency.setValueAtTime(185, time);
111→
112→  const oscGain = ctx.createGain();
113→  oscGain.gain.setValueAtTime(velocity * 0.5, time);
114→  oscGain.gain.exponentialRampToValueAtTime(0.001, time + 0.1);
115→
116→  osc.connect(oscGain).connect(destination);
117→  osc.start(time);
118→  osc.stop(time + 0.1);
119→}
120→
121→function playHiHat(
122→  ctx: AudioContext,
123→  destination: AudioNode,
124→  time: number,
125→  velocity: number,
126→  open: boolean
127→): void {
128→  const fundamental = 40;
129→  const ratios = [2, 3, 4.16, 5.43, 6.79, 8.21];
130→  const decayTime = open ? 0.3 : 0.08;
131→
132→  const bandpass = ctx.createBiquadFilter();
133→  bandpass.type = 'bandpass';
134→  bandpass.frequency.setValueAtTime(10000, time);
135→
136→  const highpass = ctx.createBiquadFilter();
137→  highpass.type = 'highpass';
138→  highpass.frequency.setValueAtTime(7000, time);
139→
140→  const gainNode = ctx.createGain();
141→  gainNode.gain.setValueAtTime(velocity * 0.3, time);
142→  gainNode.gain.exponentialRampToValueAtTime(0.001, time + decayTime);
143→
144→  bandpass.connect(highpass).connect(gainNode).connect(destination);
145→
146→  ratios.forEach((ratio) => {
147→    const osc = ctx.createOscillator();
148→    osc.type = 'square';
149→    osc.frequency.setValueAtTime(fundamental * ratio, time);
150→    osc.connect(bandpass);
151→    osc.start(time);
152→    osc.stop(time + decayTime);
153→  });
154→}
155→
156→function playTom(
157→  ctx: AudioContext,
158→  destination: AudioNode,
159→  time: number,
160→  velocity: number,
161→  pitch: 'high' | 'mid' | 'low'
162→): void {
163→  const freqMap = { high: 200, mid: 150, low: 100 };
164→  const freq = freqMap[pitch];
165→
166→  const osc = ctx.createOscillator();
167→  osc.type = 'sine';
168→  osc.frequency.setValueAtTime(freq, time);
169→  osc.frequency.exponentialRampToValueAtTime(freq * 0.5, time + 0.3);
170→
171→  const gain = ctx.createGain();
172→  gain.gain.setValueAtTime(velocity, time);
173→  gain.gain.exponentialRampToValueAtTime(0.001, time + 0.3);
174→
175→  osc.connect(gain).connect(destination);
176→  osc.start(time);
177→  osc.stop(time + 0.3);
178→}
179→
180→function playCymbal(
181→  ctx: AudioContext,
182→  destination: AudioNode,
183→  time: number,
184→  velocity: number,
185→  type: 'crash' | 'ride'
186→): void {
187→  const decayTime = type === 'crash' ? 1.5 : 0.6;
188→  const filterFreq = type === 'crash' ? 5000 : 8000;
189→
190→  const noiseBuffer = audioEngine.noiseBuffer;
191→  if (!noiseBuffer) return;
192→
193→  const source = ctx.createBufferSource();
194→  source.buffer = noiseBuffer;
195→
196→  const highpass = ctx.createBiquadFilter();
197→  highpass.type = 'highpass';
198→  highpass.frequency.setValueAtTime(filterFreq, time);
199→
200→  const gain = ctx.createGain();
201→  gain.gain.setValueAtTime(velocity * 0.4, time);
202→  gain.gain.exponentialRampToValueAtTime(0.001, time + decayTime);
203→
204→  source.connect(highpass).connect(gain).connect(destination);
205→  source.start(time);
206→  source.stop(time + decayTime);
207→}
208→

  1→import { audioEngine } from './AudioEngine';
  2→
  3→export type StepCallback = (step: number, time: number) => void;
  4→
  5→export class Scheduler {
  6→  private timerId: ReturnType<typeof setTimeout> | null = null;
  7→  private nextStepTime = 0;
  8→  private currentStep = 0;
  9→  private onStep: StepCallback | null = null;
 10→  private totalSteps = 8;
 11→  private bpm = 120;
 12→  private swing = 0;
 13→  private subdivision: '8th' | '16th' | 'triplet' = '8th';
 14→  private stepsPerBar = 8;
 15→  private barsPlayed = 0;
 16→  private stepsInCurrentBar = 0;
 17→
 18→  // Callbacks for practice mode
 19→  private onBarComplete: ((barCount: number) => void) | null = null;
 20→
 21→  private readonly LOOKAHEAD_MS = 25;
 22→  private readonly SCHEDULE_AHEAD_S = 0.1;
 23→
 24→  start(
 25→    bpm: number,
 26→    totalSteps: number,
 27→    subdivision: '8th' | '16th' | 'triplet',
 28→    swing: number,
 29→    onStep: StepCallback,
 30→    onBarComplete?: (barCount: number) => void
 31→  ): void {
 32→    this.bpm = bpm;
 33→    this.totalSteps = totalSteps;
 34→    this.subdivision = subdivision;
 35→    this.swing = swing;
 36→    this.onStep = onStep;
 37→    this.onBarComplete = onBarComplete ?? null;
 38→    this.currentStep = 0;
 39→    this.barsPlayed = 0;
 40→    this.stepsInCurrentBar = 0;
 41→    this.stepsPerBar = totalSteps;
 42→
 43→    audioEngine.init();
 44→    this.nextStepTime = audioEngine.currentTime + 0.05; // small lead time
 45→    this.schedule();
 46→  }
 47→
 48→  stop(): void {
 49→    if (this.timerId !== null) {
 50→      clearTimeout(this.timerId);
 51→      this.timerId = null;
 52→    }
 53→    this.onStep = null;
 54→    this.onBarComplete = null;
 55→  }
 56→
 57→  setBpm(bpm: number): void {
 58→    this.bpm = bpm;
 59→  }
 60→
 61→  setSwing(swing: number): void {
 62→    this.swing = swing;
 63→  }
 64→
 65→  get step(): number {
 66→    return this.currentStep;
 67→  }
 68→
 69→  get bars(): number {
 70→    return this.barsPlayed;
 71→  }
 72→
 73→  private getStepDuration(): number {
 74→    const beatsPerSecond = this.bpm / 60;
 75→    switch (this.subdivision) {
 76→      case '8th':
 77→        return 1 / (beatsPerSecond * 2);
 78→      case '16th':
 79→        return 1 / (beatsPerSecond * 4);
 80→      case 'triplet':
 81→        return 1 / (beatsPerSecond * 3);
 82→    }
 83→  }
 84→
 85→  private schedule(): void {
 86→    const stepDuration = this.getStepDuration();
 87→
 88→    while (this.nextStepTime < audioEngine.currentTime + this.SCHEDULE_AHEAD_S) {
 89→      // Apply swing to even-numbered off-beat steps
 90→      let swingOffset = 0;
 91→      if (this.currentStep % 2 === 1 && this.swing > 0) {
 92→        swingOffset = stepDuration * this.swing * 0.33;
 93→      }
 94→
 95→      const scheduledTime = this.nextStepTime + swingOffset;
 96→      this.onStep?.(this.currentStep, scheduledTime);
 97→
 98→      // Track bar progress
 99→      this.stepsInCurrentBar++;
100→      if (this.stepsInCurrentBar >= this.stepsPerBar) {
101→        this.stepsInCurrentBar = 0;
102→        this.barsPlayed++;
103→        this.onBarComplete?.(this.barsPlayed);
104→      }
105→
106→      this.nextStepTime += stepDuration;
107→      this.currentStep = (this.currentStep + 1) % this.totalSteps;
108→    }
109→
110→    this.timerId = setTimeout(() => this.schedule(), this.LOOKAHEAD_MS);
111→  }
112→}
113→

 1→export type InstrumentId =
 2→  | 'kick'
 3→  | 'snare'
 4→  | 'hihat-closed'
 5→  | 'hihat-open'
 6→  | 'tom-high'
 7→  | 'tom-mid'
 8→  | 'tom-low'
 9→  | 'crash'
10→  | 'ride';
11→
12→export interface Step {
13→  active: boolean;
14→  velocity: number; // 0.0 - 1.0
15→  accent: boolean;
16→}
17→
18→export interface Track {
19→  instrumentId: InstrumentId;
20→  label: string;
21→  steps: Step[];
22→  muted: boolean;
23→  volume: number; // 0.0 - 1.0
24→}
25→
26→export type Subdivision = '8th' | '16th' | 'triplet';
27→
28→export interface TimeSignature {
29→  beats: number;
30→  noteValue: number;
31→}
32→
33→export type PatternCategory = 'rock' | 'funk' | 'latin' | 'world' | 'rudiment';
34→
35→export type Hand = 'R' | 'L';
36→
37→export interface DrumPattern {
38→  id: string;
39→  name: string;
40→  description: string;
41→  category: PatternCategory;
