  3→import { useCallback, useRef, useState } from 'react';
  4→import { useTransportStore } from '@/lib/store/useTransportStore';
  5→
  6→export function BpmControl() {
  7→  const bpm = useTransportStore((s) => s.bpm);
  8→  const setBpm = useTransportStore((s) => s.setBpm);
  9→  const [isEditing, setIsEditing] = useState(false);
 10→  const [editValue, setEditValue] = useState('');
 11→  const tapTimesRef = useRef<number[]>([]);
 12→
 13→  const handleTap = useCallback(() => {
 14→    const now = Date.now();
 15→    const taps = tapTimesRef.current;
 16→
 17→    // Reset if last tap was more than 2 seconds ago
 18→    if (taps.length > 0 && now - taps[taps.length - 1] > 2000) {
 19→      tapTimesRef.current = [];
 20→    }
 21→
 22→    taps.push(now);
 23→
 24→    // Keep last 6 taps
 25→    if (taps.length > 6) taps.shift();
 26→
 27→    if (taps.length >= 2) {
 28→      const intervals: number[] = [];
 29→      for (let i = 1; i < taps.length; i++) {
 30→        intervals.push(taps[i] - taps[i - 1]);
 31→      }
 32→      const avgInterval = intervals.reduce((a, b) => a + b, 0) / intervals.length;
 33→      const tapBpm = Math.round(60000 / avgInterval);
 34→      setBpm(tapBpm);
 35→    }
 36→  }, [setBpm]);
 37→
 38→  const handleEditStart = () => {
 39→    setIsEditing(true);
 40→    setEditValue(String(bpm));
 41→  };
 42→
 43→  const handleEditEnd = () => {
 44→    setIsEditing(false);
 45→    const val = parseInt(editValue, 10);
 46→    if (!isNaN(val)) setBpm(val);
 47→  };
 48→
 49→  return (
 50→    <div className="flex flex-col items-center gap-3">
 51→      {/* BPM display */}
 52→      <div className="text-center">
 53→        {isEditing ? (
 54→          <input
 55→            type="number"
 56→            value={editValue}
 57→            onChange={(e) => setEditValue(e.target.value)}
 58→            onBlur={handleEditEnd}
 59→            onKeyDown={(e) => e.key === 'Enter' && handleEditEnd()}
 60→            className="w-24 text-center text-3xl font-bold bg-transparent border-b-2 border-white text-white outline-none"
 61→            min={40}
 62→            max={240}
 63→            autoFocus
 64→          />
 65→        ) : (
 66→          <button
 67→            onClick={handleEditStart}
 68→            className="text-3xl font-bold text-white cursor-pointer hover:text-gray-300 transition-colors"
 69→          >
 70→            {bpm}
 71→          </button>
 72→        )}
 73→        <div className="text-xs text-gray-500 mt-0.5">BPM</div>
 74→      </div>
 75→
 76→      {/* Slider */}
 77→      <input
 78→        type="range"
 79→        min={40}
 80→        max={240}
 81→        value={bpm}
 82→        onChange={(e) => setBpm(parseInt(e.target.value, 10))}
 83→        className="w-full h-2 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-white"
 84→      />
 85→
 86→      {/* Controls row */}
 87→      <div className="flex items-center gap-2">
 88→        <button
 89→          onClick={() => setBpm(bpm - 1)}
 90→          className="w-8 h-8 rounded bg-gray-700 text-gray-300 flex items-center justify-center
 91→                     hover:bg-gray-600 active:scale-95 transition-all cursor-pointer text-lg font-bold"
 92→        >
 93→          -
 94→        </button>
 95→        <button
 96→          onClick={handleTap}
 97→          className="px-4 h-8 rounded bg-gray-700 text-gray-300 text-xs font-medium
 98→                     hover:bg-gray-600 active:scale-95 transition-all cursor-pointer uppercase tracking-wider"
 99→        >
100→          Tap
101→        </button>
102→        <button
103→          onClick={() => setBpm(bpm + 1)}
104→          className="w-8 h-8 rounded bg-gray-700 text-gray-300 flex items-center justify-center
105→                     hover:bg-gray-600 active:scale-95 transition-all cursor-pointer text-lg font-bold"
106→        >
107→          +
108→        </button>
109→      </div>
110→    </div>
111→  );
112→}
