11→export function accentedSteps(
12→  bools: (0 | 1)[],
13→  accents: (0 | 1)[],
14→  baseVelocity = 0.6,
15→  accentVelocity = 1.0
16→): Step[] {
17→  return bools.map((b, i) => ({
18→    active: b === 1,
19→    velocity: accents[i] ? accentVelocity : baseVelocity,
20→    accent: accents[i] === 1,
21→  }));
