  1→import { audioEngine } from './AudioEngine';
  2→
  3→export type StepCallback = (step: number, time: number) => void;
  4→
  5→export class Scheduler {
  6→  private timerId: ReturnType<typeof setTimeout> | null = null;
  7→  private nextStepTime = 0;
  8→  private currentStep = 0;
  9→  private onStep: StepCallback | null = null;
 10→  private totalSteps = 8;
 11→  private bpm = 120;
 12→  private swing = 0;
 13→  private subdivision: '8th' | '16th' | 'triplet' = '8th';
 14→  private stepsPerBar = 8;
 15→  private barsPlayed = 0;
 16→  private stepsInCurrentBar = 0;
 17→
 18→  // Callbacks for practice mode
 19→  private onBarComplete: ((barCount: number) => void) | null = null;
 20→
 21→  private readonly LOOKAHEAD_MS = 25;
 22→  private readonly SCHEDULE_AHEAD_S = 0.1;
 23→
 24→  start(
 25→    bpm: number,
 26→    totalSteps: number,
 27→    subdivision: '8th' | '16th' | 'triplet',
 28→    swing: number,
 29→    onStep: StepCallback,
 30→    onBarComplete?: (barCount: number) => void
 31→  ): void {
 32→    this.bpm = bpm;
 33→    this.totalSteps = totalSteps;
 34→    this.subdivision = subdivision;
 35→    this.swing = swing;
 36→    this.onStep = onStep;
 37→    this.onBarComplete = onBarComplete ?? null;
 38→    this.currentStep = 0;
 39→    this.barsPlayed = 0;
 40→    this.stepsInCurrentBar = 0;
 41→    this.stepsPerBar = totalSteps;
 42→
 43→    audioEngine.init();
 44→    this.nextStepTime = audioEngine.currentTime + 0.05; // small lead time
 45→    this.schedule();
 46→  }
 47→
 48→  stop(): void {
 49→    if (this.timerId !== null) {
 50→      clearTimeout(this.timerId);
 51→      this.timerId = null;
 52→    }
 53→    this.onStep = null;
 54→    this.onBarComplete = null;
 55→  }
 56→
 57→  setBpm(bpm: number): void {
 58→    this.bpm = bpm;
 59→  }
 60→
 61→  setSwing(swing: number): void {
 62→    this.swing = swing;
 63→  }
 64→
 65→  get step(): number {
 66→    return this.currentStep;
 67→  }
 68→
 69→  get bars(): number {
 70→    return this.barsPlayed;
 71→  }
 72→
 73→  private getStepDuration(): number {
 74→    const beatsPerSecond = this.bpm / 60;
 75→    switch (this.subdivision) {
 76→      case '8th':
 77→        return 1 / (beatsPerSecond * 2);
 78→      case '16th':
 79→        return 1 / (beatsPerSecond * 4);
 80→      case 'triplet':
 81→        return 1 / (beatsPerSecond * 3);
 82→    }
 83→  }
 84→
 85→  private schedule(): void {
 86→    const stepDuration = this.getStepDuration();
 87→
 88→    while (this.nextStepTime < audioEngine.currentTime + this.SCHEDULE_AHEAD_S) {
 89→      // Apply swing to even-numbered off-beat steps
 90→      let swingOffset = 0;
 91→      if (this.currentStep % 2 === 1 && this.swing > 0) {
 92→        swingOffset = stepDuration * this.swing * 0.33;
 93→      }
 94→
 95→      const scheduledTime = this.nextStepTime + swingOffset;
 96→      this.onStep?.(this.currentStep, scheduledTime);
 97→
 98→      // Track bar progress
 99→      this.stepsInCurrentBar++;
100→      if (this.stepsInCurrentBar >= this.stepsPerBar) {
101→        this.stepsInCurrentBar = 0;
102→        this.barsPlayed++;
103→        this.onBarComplete?.(this.barsPlayed);
104→      }
105→
106→      this.nextStepTime += stepDuration;
107→      this.currentStep = (this.currentStep + 1) % this.totalSteps;
108→    }
109→
110→    this.timerId = setTimeout(() => this.schedule(), this.LOOKAHEAD_MS);
111→  }
112→}
