 7→export function PracticeStats() {
 8→  const barsPlayed = usePracticeStore((s) => s.barsPlayed);
 9→  const sessionStartTime = usePracticeStore((s) => s.sessionStartTime);
10→  const playState = useTransportStore((s) => s.playState);
11→  const bpm = useTransportStore((s) => s.bpm);
12→  const [elapsed, setElapsed] = useState(0);
13→
14→  useEffect(() => {
15→    if (playState !== 'playing' || !sessionStartTime) return;
16→
17→    const interval = setInterval(() => {
18→      setElapsed(Math.floor((Date.now() - sessionStartTime) / 1000));
19→    }, 1000);
20→
21→    return () => clearInterval(interval);
22→  }, [playState, sessionStartTime]);
23→
24→  const minutes = Math.floor(elapsed / 60);
25→  const seconds = elapsed % 60;
26→  const timeStr = `${minutes}:${seconds.toString().padStart(2, '0')}`;
27→
28→  if (playState === 'stopped' && barsPlayed === 0) return null;
29→
30→  return (
31→    <div className="flex items-center gap-4 text-xs text-gray-400">
32→      <div className="flex items-center gap-1.5">
33→        <div className="w-1.5 h-1.5 rounded-full bg-gray-600" />
34→        <span>{timeStr}</span>
35→      </div>
36→      <div className="flex items-center gap-1.5">
37→        <span>Bars: {barsPlayed}</span>
38→      </div>
39→      <div className="flex items-center gap-1.5">
