#### 6d. Hook: `useLiveKeyboardHandler.ts`

```typescript
// Handles keydown events for drum taps during live practice.
// Critical design: uses audioEngine.currentTime at the moment of keydown
// for sub-millisecond precision (vs Date.now() which is limited by event
// loop granularity).

export function useLiveKeyboardHandler(
  tapMatcher: TapMatcher,
  isActive: boolean
) {
  useEffect(() => {
    if (!isActive) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.repeat) return; // ignore key repeat
      if (e.target instanceof HTMLInputElement) return;

      const { keyMappings } = useLivePracticeStore.getState();
      const mapping = keyMappings.find(m => m.key === e.code);
      if (!mapping) return;

      e.preventDefault();

      // Record timestamp from audio clock
      const tapTime = audioEngine.currentTime;

      // Play the instrument sound immediately
      playInstrument(mapping.instrumentId, tapTime, 0.8, 0.8);

      // Process through TapMatcher
      const tapEvent = tapMatcher.processTap(tapTime, mapping.instrumentId);

      // Update store
      useLivePracticeStore.getState().recordTap(tapEvent);
      if (tapEvent.matchedStep !== null) {
        useLivePracticeStore.getState().setStepAccuracy(
          tapEvent.matchedStep,
          mapping.instrumentId,
          tapEvent.grade,
          tapEvent.offset
        );
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isActive, tapMatcher]);
}
```

