'use client';

import React, { useCallback, useRef, useState } from 'react';
import { InstrumentId } from '@/lib/patterns/types';
import { audioEngine } from '@/lib/audio/AudioEngine';
import { playInstrument } from '@/lib/audio/DrumSynth';
import { TapMatcher } from '@/lib/live-practice/TapMatcher';
import { useLivePracticeStore } from '@/lib/store/useLivePracticeStore';
import { TimingGrade, GRADE_COLORS } from '@/lib/live-practice/types';

const instrumentPadColors: Record<InstrumentId, string> = {
  kick: 'border-red-500/50 hover:border-red-500',
  snare: 'border-yellow-400/50 hover:border-yellow-400',
  'hihat-closed': 'border-cyan-400/50 hover:border-cyan-400',
  'hihat-open': 'border-cyan-300/50 hover:border-cyan-300',
  'tom-high': 'border-purple-400/50 hover:border-purple-400',
  'tom-mid': 'border-purple-500/50 hover:border-purple-500',
  'tom-low': 'border-purple-600/50 hover:border-purple-600',
  crash: 'border-orange-400/50 hover:border-orange-400',
  ride: 'border-green-400/50 hover:border-green-400',
};

interface TapPadProps {
  instrumentId: InstrumentId;
  label: string;
  keyLabel: string;
  tapMatcher: TapMatcher | null;
  isActive: boolean;
}

export const TapPad = React.memo(function TapPad({
  instrumentId,
  label,
  keyLabel,
  tapMatcher,
  isActive,
}: TapPadProps) {
  const [flash, setFlash] = useState<TimingGrade | null>(null);
  const flashTimeout = useRef<ReturnType<typeof setTimeout>>();

  const handleTap = useCallback(() => {
    if (!tapMatcher || !isActive) return;

    const tapTime = audioEngine.currentTime;
    playInstrument(instrumentId, tapTime, 0.8, 0.8);

    const tapEvent = tapMatcher.processTap(tapTime, instrumentId);
    const store = useLivePracticeStore.getState();
    store.recordTap(tapEvent);
    if (tapEvent.matchedStep !== null) {
      store.setStepAccuracy(
        tapEvent.matchedStep,
        instrumentId,
        tapEvent.grade,
        tapEvent.offset
      );
    }

    // Visual flash
    setFlash(tapEvent.grade);
    if (flashTimeout.current) clearTimeout(flashTimeout.current);
    flashTimeout.current = setTimeout(() => setFlash(null), 200);
  }, [instrumentId, tapMatcher, isActive]);

  const padColor = instrumentPadColors[instrumentId];
  const flashColor = flash ? GRADE_COLORS[flash] : '';

  return (
    <button
      onMouseDown={(e) => { e.preventDefault(); handleTap(); }}
      onTouchStart={(e) => { e.preventDefault(); handleTap(); }}
      className={`
        relative flex flex-col items-center justify-center
        w-16 h-16 sm:w-20 sm:h-20 rounded-xl border-2 cursor-pointer
        bg-gray-800/80 transition-all duration-75 select-none
        active:scale-90
        ${padColor}
        ${flash ? `${flashColor} scale-95` : ''}
      `}
    >
      <span className="text-xs sm:text-sm font-medium text-gray-200">{label}</span>
      <span className="text-[10px] text-gray-500 mt-0.5">{keyLabel}</span>
    </button>
  );
});

'use client';

import { usePatternStore } from '@/lib/store/usePatternStore';
import { useLivePracticeStore } from '@/lib/store/useLivePracticeStore';
import { TapMatcher } from '@/lib/live-practice/TapMatcher';
import { TapPad } from './TapPad';

interface TapPadPanelProps {
  tapMatcher: TapMatcher | null;
  isActive: boolean;
}

export function TapPadPanel({ tapMatcher, isActive }: TapPadPanelProps) {
  const tracks = usePatternStore((s) => s.currentPattern.tracks);
  const keyMappings = useLivePracticeStore((s) => s.keyMappings);
  const mode = useLivePracticeStore((s) => s.mode);
  const focusedTrack = useLivePracticeStore((s) => s.focusedTrack);

  // In single-track mode, only show the focused track's pad
  const visibleTracks = mode === 'single-track' && focusedTrack
    ? tracks.filter((t) => t.instrumentId === focusedTrack)
    : tracks;

  return (
    <div className="bg-[#1a1d27] rounded-xl p-4 border border-gray-800">
      <div className="text-xs text-gray-500 uppercase tracking-wider font-medium mb-3">
        Tap Pads
      </div>
      <div className="flex flex-wrap gap-2 justify-center">
        {visibleTracks.map((track) => {
          const mapping = keyMappings.find(
            (m) => m.instrumentId === track.instrumentId
          );
          return (
            <TapPad
              key={track.instrumentId}
              instrumentId={track.instrumentId}
              label={track.label}
              keyLabel={mapping?.label ?? ''}
              tapMatcher={tapMatcher}
              isActive={isActive}
            />
          );
        })}
      </div>
    </div>
  );
}

'use client';

import { useLivePracticeStore } from '@/lib/store/useLivePracticeStore';
import { GRADE_TEXT_COLORS } from '@/lib/live-practice/types';

export function LiveStatsPanel() {
  const stats = useLivePracticeStore((s) => s.stats);
  const lastGrade = useLivePracticeStore((s) => s.lastTapGrade);
  const isActive = useLivePracticeStore((s) => s.isActive);

  const accuracy = stats.totalExpected > 0
    ? Math.round((stats.totalHits / stats.totalExpected) * 100)
    : 0;

  const avgOffsetMs = Math.round(stats.averageOffset * 1000);
  const offsetLabel = avgOffsetMs === 0
    ? 'On beat'
    : avgOffsetMs > 0
      ? `+${avgOffsetMs}ms (late)`
      : `${avgOffsetMs}ms (early)`;

  if (!isActive && stats.totalExpected === 0) return null;

  return (
    <div className="bg-[#1a1d27] rounded-xl p-4 border border-gray-800">
      <div className="text-xs text-gray-500 uppercase tracking-wider font-medium mb-3">
        Stats
      </div>

      <div className="grid grid-cols-2 gap-3">
        {/* Accuracy */}
        <div>
          <div className="text-2xl font-bold text-white">{accuracy}%</div>
          <div className="text-xs text-gray-500">Accuracy</div>
        </div>

        {/* Streak */}
        <div>
          <div className="text-2xl font-bold text-white">{stats.currentStreak}</div>
          <div className="text-xs text-gray-500">
            Streak {stats.bestStreak > 0 && `(best: ${stats.bestStreak})`}
          </div>
        </div>

        {/* Timing */}
        <div>
          <div className="text-sm font-medium text-gray-300">{offsetLabel}</div>
          <div className="text-xs text-gray-500">Avg timing</div>
        </div>

        {/* Last grade */}
        <div>
          {lastGrade && (
            <div className={`text-sm font-bold uppercase ${GRADE_TEXT_COLORS[lastGrade]}`}>
              {lastGrade}
            </div>
          )}
          <div className="text-xs text-gray-500">Last tap</div>
        </div>
      </div>

      {/* Grade breakdown */}
      {stats.totalExpected > 0 && (
        <div className="mt-3 pt-3 border-t border-gray-800">
          <div className="flex gap-3 text-xs">
            <span className="text-green-400">{stats.perfectCount} perfect</span>
            <span className="text-lime-400">{stats.greatCount} great</span>
            <span className="text-yellow-400">{stats.goodCount} good</span>
            <span className="text-orange-400">{stats.earlyLateCount} off</span>
            <span className="text-red-500">{stats.totalMisses} miss</span>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useLivePracticeStore } from '@/lib/store/useLivePracticeStore';
import { GRADE_TEXT_COLORS } from '@/lib/live-practice/types';

interface LiveResultsModalProps {
  isOpen: boolean;
  onClose: () => void;
  onRetry: () => void;
}

export function LiveResultsModal({ isOpen, onClose, onRetry }: LiveResultsModalProps) {
  const stats = useLivePracticeStore((s) => s.stats);

  if (!isOpen || stats.totalExpected === 0) return null;

  const accuracy = Math.round((stats.totalHits / stats.totalExpected) * 100);
  const avgOffsetMs = Math.round(stats.averageOffset * 1000);

  let overallGrade: string;
  let gradeColor: string;
  if (accuracy >= 90) { overallGrade = 'Excellent'; gradeColor = 'text-green-400'; }
  else if (accuracy >= 75) { overallGrade = 'Great'; gradeColor = 'text-lime-400'; }
  else if (accuracy >= 60) { overallGrade = 'Good'; gradeColor = 'text-yellow-400'; }
  else if (accuracy >= 40) { overallGrade = 'Keep Practicing'; gradeColor = 'text-orange-400'; }
  else { overallGrade = 'Try Slower'; gradeColor = 'text-red-400'; }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm">
      <div className="bg-[#1a1d27] rounded-2xl p-6 border border-gray-700 max-w-sm w-full mx-4">
        <h2 className="text-lg font-bold text-center mb-1">Session Complete</h2>
        <div className={`text-center text-2xl font-bold mb-4 ${gradeColor}`}>
          {overallGrade}
        </div>

        {/* Big accuracy number */}
        <div className="text-center mb-4">
          <div className="text-5xl font-bold text-white">{accuracy}%</div>
          <div className="text-sm text-gray-500 mt-1">
            {stats.totalHits}/{stats.totalExpected} hits
          </div>
        </div>

        {/* Stats grid */}
        <div className="grid grid-cols-2 gap-3 mb-4">
          <div className="bg-gray-800/50 rounded-lg p-2 text-center">
            <div className="text-lg font-bold text-white">{stats.bestStreak}</div>
            <div className="text-xs text-gray-500">Best Streak</div>
          </div>
          <div className="bg-gray-800/50 rounded-lg p-2 text-center">
            <div className="text-lg font-bold text-white">
              {avgOffsetMs > 0 ? '+' : ''}{avgOffsetMs}ms
            </div>
            <div className="text-xs text-gray-500">Avg Timing</div>
          </div>
        </div>

        {/* Grade breakdown */}
        <div className="bg-gray-800/50 rounded-lg p-3 mb-5">
          <div className="grid grid-cols-5 gap-1 text-center text-xs">
            <div>
              <div className={`font-bold ${GRADE_TEXT_COLORS.perfect}`}>{stats.perfectCount}</div>
              <div className="text-gray-600">Perfect</div>
            </div>
            <div>
              <div className={`font-bold ${GRADE_TEXT_COLORS.great}`}>{stats.greatCount}</div>
              <div className="text-gray-600">Great</div>
            </div>
            <div>
              <div className={`font-bold ${GRADE_TEXT_COLORS.good}`}>{stats.goodCount}</div>
              <div className="text-gray-600">Good</div>
            </div>
            <div>
              <div className={`font-bold ${GRADE_TEXT_COLORS.early}`}>{stats.earlyLateCount}</div>
              <div className="text-gray-600">Off</div>
            </div>
            <div>
              <div className={`font-bold ${GRADE_TEXT_COLORS.miss}`}>{stats.totalMisses}</div>
              <div className="text-gray-600">Miss</div>
            </div>
          </div>
        </div>

        {/* Actions */}
        <div className="flex gap-3">
          <button
            onClick={onRetry}
            className="flex-1 h-10 rounded-lg bg-white text-gray-900 font-medium text-sm
                       hover:bg-gray-200 active:scale-95 transition-all cursor-pointer"
          >
            Try Again
          </button>
          <button
            onClick={onClose}
            className="flex-1 h-10 rounded-lg bg-gray-700 text-gray-300 font-medium text-sm
                       hover:bg-gray-600 active:scale-95 transition-all cursor-pointer"
          >
            Back to Patterns
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

import { usePatternStore } from '@/lib/store/usePatternStore';
import { useLivePracticeStore } from '@/lib/store/useLivePracticeStore';
import { LiveMode } from '@/lib/live-practice/types';
import { InstrumentId } from '@/lib/patterns/types';

const modes: { id: LiveMode; label: string; description: string }[] = [
  { id: 'full-kit', label: 'Full Kit', description: 'Play all instruments' },
  { id: 'single-track', label: 'Single Track', description: 'Focus on one instrument' },
];

export function ModeSelector() {
  const mode = useLivePracticeStore((s) => s.mode);
  const setMode = useLivePracticeStore((s) => s.setMode);
  const focusedTrack = useLivePracticeStore((s) => s.focusedTrack);
  const setFocusedTrack = useLivePracticeStore((s) => s.setFocusedTrack);
  const tracks = usePatternStore((s) => s.currentPattern.tracks);

  return (
    <div className="flex flex-col gap-2">
      <div className="flex gap-2">
        {modes.map((m) => (
          <button
            key={m.id}
            onClick={() => {
              setMode(m.id);
              if (m.id === 'single-track' && !focusedTrack && tracks.length > 0) {
                setFocusedTrack(tracks[0].instrumentId);
              }
            }}
            className={`
              px-3 py-1.5 rounded-lg text-xs font-medium transition-all cursor-pointer
              ${mode === m.id
                ? 'bg-white text-gray-900'
                : 'bg-gray-800 text-gray-400 hover:bg-gray-700 hover:text-gray-300'
              }
            `}
            title={m.description}
          >
            {m.label}
          </button>
        ))}
      </div>

      {mode === 'single-track' && (
        <div className="flex flex-wrap gap-1">
          {tracks.map((track) => (
            <button
              key={track.instrumentId}
              onClick={() => setFocusedTrack(track.instrumentId as InstrumentId)}
              className={`
                px-2 py-1 rounded text-xs transition-all cursor-pointer
                ${focusedTrack === track.instrumentId
                  ? 'bg-gray-600 text-white'
                  : 'bg-gray-800 text-gray-500 hover:text-gray-300'
                }
              `}
            >
              {track.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

