  1→'use client';
  2→
  3→import { useState } from 'react';
  4→import { useRouter } from 'next/navigation';
  5→import { Header } from '@/components/Header';
  6→import { allPatterns, categories } from '@/lib/patterns';
  7→import { usePatternStore } from '@/lib/store/usePatternStore';
  8→import { useTransportStore } from '@/lib/store/useTransportStore';
  9→import { PatternCategory } from '@/lib/patterns/types';
 10→
 11→const categoryColors: Record<string, string> = {
 12→  rock: 'bg-red-500/20 text-red-400',
 13→  funk: 'bg-purple-500/20 text-purple-400',
 14→  latin: 'bg-yellow-500/20 text-yellow-400',
 15→  world: 'bg-green-500/20 text-green-400',
 16→  rudiment: 'bg-cyan-500/20 text-cyan-400',
 17→};
 18→
 19→export default function Home() {
 20→  const [activeCategory, setActiveCategory] = useState<PatternCategory | 'all'>('all');
 21→  const loadPattern = usePatternStore((s) => s.loadPattern);
 22→  const setBpm = useTransportStore((s) => s.setBpm);
 23→  const stop = useTransportStore((s) => s.stop);
 24→  const router = useRouter();
 25→
 26→  const filtered = activeCategory === 'all'
 27→    ? allPatterns
 28→    : allPatterns.filter((p) => p.category === activeCategory);
 29→
 30→  const handleSelect = (patternId: string) => {
 31→    const pattern = allPatterns.find((p) => p.id === patternId);
 32→    if (!pattern) return;
 33→    stop();
 34→    loadPattern(pattern);
 35→    setBpm(pattern.defaultBpm);
 36→    router.push('/practice');
 37→  };
 38→
 39→  return (
 40→    <div className="min-h-screen">
 41→      <Header />
 42→      <main className="max-w-5xl mx-auto px-4 py-8">
 43→        <div className="mb-8">
 44→          <h1 className="text-2xl font-bold mb-2">Pattern Library</h1>
 45→          <p className="text-gray-400 text-sm">
 46→            Choose a pattern to practice. Click any pattern to load it in the practice view.
 47→          </p>
 48→        </div>
 49→
 50→        {/* Category filter */}
 51→        <div className="flex flex-wrap gap-2 mb-6">
 52→          {categories.map((cat) => (
 53→            <button
 54→              key={cat.id}
 55→              onClick={() => setActiveCategory(cat.id)}
 56→              className={`
 57→                px-3 py-1.5 rounded-lg text-sm font-medium transition-all cursor-pointer
 58→                ${activeCategory === cat.id
 59→                  ? 'bg-white text-gray-900'
 60→                  : 'bg-gray-800 text-gray-400 hover:bg-gray-700 hover:text-gray-300'
 61→                }
 62→              `}
 63→            >
 64→              {cat.label}
 65→            </button>
 66→          ))}
 67→        </div>
 68→
 69→        {/* Pattern grid */}
 70→        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
 71→          {filtered.map((pattern) => (
 72→            <button
 73→              key={pattern.id}
 74→              onClick={() => handleSelect(pattern.id)}
 75→              className="text-left bg-[#1a1d27] rounded-xl p-4 border border-gray-800
 76→                         hover:border-gray-600 hover:bg-[#1e2130] transition-all cursor-pointer group"
 77→            >
 78→              <div className="flex items-start justify-between mb-2">
 79→                <h3 className="font-semibold text-sm group-hover:text-white transition-colors">
 80→                  {pattern.name}
 81→                </h3>
 82→                <span className={`text-xs px-2 py-0.5 rounded-full ${categoryColors[pattern.category] ?? 'bg-gray-700 text-gray-400'}`}>
 83→                  {pattern.category}
 84→                </span>
 85→              </div>
 86→              <p className="text-xs text-gray-500 mb-3 line-clamp-2">
 87→                {pattern.description}
 88→              </p>
 89→              <div className="flex items-center gap-3 text-xs text-gray-500">
 90→                <span>{pattern.defaultBpm} BPM</span>
 91→                <span>{pattern.timeSignature.beats}/{pattern.timeSignature.noteValue}</span>
 92→                <span>{pattern.subdivision}</span>
 93→                <span>{pattern.tracks.length} tracks</span>
 94→              </div>
 95→
 96→              {/* Mini grid preview */}
 97→              <div className="mt-3 flex flex-col gap-0.5">
 98→                {pattern.tracks.slice(0, 3).map((track, ti) => (
 99→                  <div key={ti} className="flex gap-px">
100→                    {track.steps.map((step, si) => (
101→                      <div
102→                        key={si}
