  1→import { create } from 'zustand';
  2→import { PlayState, Track } from '../patterns/types';
  3→import { Scheduler } from '../audio/Scheduler';
  4→import { playInstrument } from '../audio/DrumSynth';
  5→import { audioEngine } from '../audio/AudioEngine';
  6→
  7→export const scheduler = new Scheduler();
  8→
  9→// Lazy accessors to avoid circular imports
 10→function getPatternState() {
 11→  // eslint-disable-next-line @typescript-eslint/no-require-imports
 12→  const { usePatternStore } = require('./usePatternStore');
 13→  return usePatternStore.getState() as {
 14→    currentPattern: {
 15→      tracks: Track[];
 16→      totalSteps: number;
 17→      subdivision: '8th' | '16th' | 'triplet';
 18→    };
 19→  };
 20→}
 21→
 22→function getPracticeState() {
 23→  // eslint-disable-next-line @typescript-eslint/no-require-imports
 24→  const { usePracticeStore } = require('./usePracticeStore');
 25→  return usePracticeStore as {
 26→    getState: () => {
 27→      mode: string;
 28→      tempoRampConfig: { incrementBpm: number; endBpm: number; barsPerIncrement: number };
 29→    };
 30→    setState: (state: Record<string, unknown>) => void;
 31→  };
 32→}
 33→
 34→interface TransportStore {
 35→  playState: PlayState;
 36→  bpm: number;
 37→  currentStep: number;
 38→  swing: number;
 39→
 40→  play: () => void;
 41→  pause: () => void;
 42→  stop: () => void;
 43→  setBpm: (bpm: number) => void;
 44→  setCurrentStep: (step: number) => void;
 45→  setSwing: (swing: number) => void;
 46→}
 47→
 48→export const useTransportStore = create<TransportStore>((set, get) => ({
 49→  playState: 'stopped',
 50→  bpm: 100,
 51→  currentStep: -1,
 52→  swing: 0,
 53→
 54→  play: () => {
 55→    const { currentPattern: pattern } = getPatternState();
 56→    const { bpm, swing } = get();
 57→
 58→    audioEngine.init();
 59→
 60→    const onStep = (step: number, time: number) => {
 61→      // Re-read pattern each step to pick up live edits
 62→      const { currentPattern: livePattern } = getPatternState();
 63→      livePattern.tracks.forEach((track: Track) => {
 64→        if (track.muted) return;
 65→        const s = track.steps[step];
 66→        if (s && s.active) {
 67→          playInstrument(track.instrumentId, time, s.velocity, track.volume);
 68→        }
 69→      });
 70→
 71→      // Schedule UI update synced to audio time
 72→      const delayMs = Math.max(0, (time - audioEngine.currentTime) * 1000);
 73→      setTimeout(() => {
 74→        set({ currentStep: step });
 75→      }, delayMs);
 76→    };
 77→
 78→    const practiceStore = getPracticeState();
 79→    const practiceState = practiceStore.getState();
 80→    const onBarComplete = practiceState.mode === 'tempo-ramp'
 81→      ? (barCount: number) => {
 82→          const ps = practiceStore.getState();
 83→          if (ps.mode === 'tempo-ramp' && ps.tempoRampConfig) {
 84→            const config = ps.tempoRampConfig;
 85→            if (barCount > 0 && barCount % config.barsPerIncrement === 0) {
 86→              const currentBpm = get().bpm;
 87→              const newBpm = Math.min(currentBpm + config.incrementBpm, config.endBpm);
 88→              if (newBpm !== currentBpm) {
 89→                set({ bpm: newBpm });
 90→                scheduler.setBpm(newBpm);
 91→                practiceStore.setState({ currentBpm: newBpm });
 92→              }
 93→            }
 94→          }
 95→          practiceStore.setState({ barsPlayed: barCount });
 96→        }
 97→      : undefined;
 98→
 99→    scheduler.start(bpm, pattern.totalSteps, pattern.subdivision, swing, onStep, onBarComplete);
100→    set({ playState: 'playing' });
101→  },
102→
103→  pause: () => {
104→    scheduler.stop();
105→    set({ playState: 'paused' });
106→  },
107→
108→  stop: () => {
109→    scheduler.stop();
110→    set({ playState: 'stopped', currentStep: -1 });
111→  },
112→
113→  setBpm: (bpm: number) => {
114→    const clamped = Math.max(40, Math.min(240, bpm));
115→    set({ bpm: clamped });
116→    scheduler.setBpm(clamped);
117→  },
118→
119→  setCurrentStep: (step: number) => set({ currentStep: step }),
120→
121→  setSwing: (swing: number) => {
122→    set({ swing });
123→    scheduler.setSwing(swing);
124→  },
125→}));
