 1→'use client';
 2→
 3→import { useEffect } from 'react';
 4→import { useTransportStore } from '../store/useTransportStore';
 5→
 6→export function useKeyboardShortcuts() {
 7→  useEffect(() => {
 8→    const handleKeyDown = (e: KeyboardEvent) => {
 9→      // Don't trigger shortcuts when typing in inputs
10→      if (
11→        e.target instanceof HTMLInputElement ||
12→        e.target instanceof HTMLTextAreaElement
13→      ) {
14→        return;
15→      }
16→
17→      const { playState, play, pause, stop, setBpm, bpm } =
18→        useTransportStore.getState();
19→
20→      switch (e.code) {
21→        case 'Space':
22→          e.preventDefault();
23→          if (playState === 'playing') {
24→            pause();
25→          } else {
26→            play();
27→          }
28→          break;
29→        case 'Escape':
30→          stop();
31→          break;
32→        case 'ArrowUp':
33→          e.preventDefault();
34→          setBpm(bpm + (e.shiftKey ? 10 : 1));
35→          break;
36→        case 'ArrowDown':
37→          e.preventDefault();
38→          setBpm(bpm - (e.shiftKey ? 10 : 1));
39→          break;
40→      }
41→    };
42→
43→    window.addEventListener('keydown', handleKeyDown);
44→    return () => window.removeEventListener('keydown', handleKeyDown);
45→  }, []);
46→}
