 7→export function useStopOnNavigate() {
 8→  const pathname = usePathname();
 9→  const stop = useTransportStore((s) => s.stop);
10→  const playState = useTransportStore((s) => s.playState);
11→
12→  // Stop playback on route change
13→  useEffect(() => {
14→    if (playState === 'playing') {
15→      stop();
16→    }
17→    // Only trigger on pathname changes, not on play/stop state changes
18→    // eslint-disable-next-line react-hooks/exhaustive-deps
19→  }, [pathname]);
20→
21→  // Stop playback when tab becomes hidden
22→  useEffect(() => {
23→    const handleVisibilityChange = () => {
24→      if (document.hidden && useTransportStore.getState().playState === 'playing') {
25→        useTransportStore.getState().stop();
26→      }
27→    };
28→
29→    document.addEventListener('visibilitychange', handleVisibilityChange);
30→    return () => document.removeEventListener('visibilitychange', handleVisibilityChange);
31→  }, []);
32→}
