 22→export default function LivePracticePage() {
 23→  const pattern = usePatternStore((s) => s.currentPattern);
 24→  const playState = useTransportStore((s) => s.playState);
 25→  const play = useTransportStore((s) => s.play);
 26→  const stop = useTransportStore((s) => s.stop);
 27→  const bpm = useTransportStore((s) => s.bpm);
 28→
 29→  const isActive = useLivePracticeStore((s) => s.isActive);
 30→  const startSession = useLivePracticeStore((s) => s.startSession);
 31→  const endSession = useLivePracticeStore((s) => s.endSession);
 32→  const mode = useLivePracticeStore((s) => s.mode);
 33→  const focusedTrack = useLivePracticeStore((s) => s.focusedTrack);
 34→  const stepAccuraciesRaw = useLivePracticeStore((s) => s.stepAccuracies);
 35→  const recordMiss = useLivePracticeStore((s) => s.recordMiss);
 36→  const resetStepAccuracies = useLivePracticeStore((s) => s.resetStepAccuracies);
 37→  const stats = useLivePracticeStore((s) => s.stats);
 38→
 39→  const [showResults, setShowResults] = useState(false);
 40→
 41→  const tapMatcherRef = useRef<TapMatcher | null>(null);
 42→  const sweepIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
 43→
 44→  // Initialize TapMatcher
 45→  if (!tapMatcherRef.current) {
 46→    tapMatcherRef.current = new TapMatcher();
 47→  }
 48→
 49→  // Convert stepAccuracies to the format BeatGrid expects: Record<string, TimingGrade>
 50→  const stepAccuracies = useMemo(() => {
 51→    const result: Record<string, TimingGrade> = {};
 52→    for (const [key, acc] of Object.entries(stepAccuraciesRaw)) {
 53→      result[key] = acc.grade;
 54→    }
 55→    return result;
 56→  }, [stepAccuraciesRaw]);
 57→
 58→  // Register step listener for feeding expected beats to TapMatcher
 59→  useEffect(() => {
 60→    const unsubscribe = scheduler.addStepListener((step, time) => {
 61→      const tapMatcher = tapMatcherRef.current;
 62→      if (!tapMatcher || !useLivePracticeStore.getState().isActive) return;
 63→
 64→      const liveMode = useLivePracticeStore.getState().mode;
 65→      const focused = useLivePracticeStore.getState().focusedTrack;
 66→      const currentPattern = usePatternStore.getState().currentPattern;
 67→
 68→      currentPattern.tracks.forEach((track: Track) => {
 69→        const s = track.steps[step];
 70→        if (!s || !s.active) return;
 71→
 72→        // In single-track mode, only expect beats for the focused instrument
 73→        if (liveMode === 'single-track' && focused && track.instrumentId !== focused) return;
 74→
 75→        tapMatcher.addExpectedBeat(step, time, track.instrumentId);
 76→      });
 77→    });
 78→
 79→    return unsubscribe;
 80→  }, []);
 81→
 82→  // Sweep for misses periodically
 83→  useEffect(() => {
 84→    if (isActive) {
 85→      sweepIntervalRef.current = setInterval(() => {
 86→        const tapMatcher = tapMatcherRef.current;
 87→        if (!tapMatcher) return;
 88→        const misses = tapMatcher.sweepMisses(audioEngine.currentTime);
 89→        misses.forEach((miss) => {
 90→          recordMiss(miss.step, miss.instrumentId);
 91→        });
 92→      }, 50);
 93→    } else {
 94→      if (sweepIntervalRef.current) {
 95→        clearInterval(sweepIntervalRef.current);
 96→      }
 97→    }
 98→
 99→    return () => {
100→      if (sweepIntervalRef.current) {
101→        clearInterval(sweepIntervalRef.current);
102→      }
103→    };
104→  }, [isActive, recordMiss]);
105→
106→  // Reset step accuracy display each bar (so colors don't pile up forever)
107→  useEffect(() => {
108→    const unsubscribe = scheduler.addStepListener((step) => {
109→      if (step === 0 && useLivePracticeStore.getState().isActive) {
110→        useLivePracticeStore.getState().resetStepAccuracies();
111→      }
112→    });
113→    return unsubscribe;
114→  }, []);
115→
116→  // Handle keyboard taps
117→  useLiveKeyboardHandler(tapMatcherRef.current, isActive);
118→
119→  // Handle play/stop with session tracking
120→  const handlePlay = useCallback(() => {
121→    tapMatcherRef.current?.reset();
122→    startSession();
123→    resetStepAccuracies();
124→    play();
125→  }, [play, startSession, resetStepAccuracies]);
126→
127→  const handleStop = useCallback(() => {
128→    stop();
129→    // Final sweep for any remaining expected beats
130→    if (tapMatcherRef.current) {
131→      const misses = tapMatcherRef.current.sweepMisses(Infinity);
132→      const rm = useLivePracticeStore.getState().recordMiss;
133→      misses.forEach((miss) => rm(miss.step, miss.instrumentId));
134→    }
135→    endSession();
136→    // Show results if there was data
137→    if (useLivePracticeStore.getState().stats.totalExpected > 0) {
138→      setShowResults(true);
139→    }
140→  }, [stop, endSession]);
141→
142→  const handleRetry = useCallback(() => {
143→    setShowResults(false);
144→    handlePlay();
145→  }, [handlePlay]);
146→
147→  const router = useRouter();
148→  const handleBackToPatterns = useCallback(() => {
149→    setShowResults(false);
150→    router.push('/');
151→  }, [router]);
152→
153→  return (
154→    <div className="min-h-screen">
155→      <Header />
156→      <main className="max-w-5xl mx-auto px-4 py-6">
157→        {/* Pattern info + mode */}
158→        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-4">
159→          <div>
160→            <div className="flex items-center gap-3 mb-1">
161→              <h1 className="text-xl font-bold">{pattern.name}</h1>
162→              <span className="text-xs bg-gray-800 text-gray-400 px-2 py-0.5 rounded-full">
163→                {pattern.timeSignature.beats}/{pattern.timeSignature.noteValue}
164→              </span>
165→              <span className="text-xs bg-gray-800 text-gray-400 px-2 py-0.5 rounded-full">
166→                {pattern.subdivision}
167→              </span>
168→            </div>
169→            <p className="text-sm text-gray-500">{pattern.description}</p>
170→          </div>
171→          <ModeSelector />
172→        </div>
173→
174→        {/* Beat grid with accuracy overlay */}
175→        <div className="mb-4 overflow-x-auto">
176→          <BeatGrid stepAccuracies={isActive || stats.totalExpected > 0 ? stepAccuracies : undefined} />
177→        </div>
178→
179→        {/* Controls + pads + stats */}
180→        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
181→          {/* Transport + BPM */}
182→          <div className="flex flex-col gap-4">
183→            <div className="bg-[#1a1d27] rounded-xl p-4 border border-gray-800">
184→              <div className="flex items-center gap-3 mb-4">
185→                {/* Custom play/stop that manages sessions */}
186→                <button
187→                  onClick={playState === 'playing' ? handleStop : handlePlay}
188→                  className="w-14 h-14 rounded-full bg-white text-gray-900 flex items-center justify-center
189→                             hover:bg-gray-200 active:scale-95 transition-all cursor-pointer shadow-lg"
190→                  aria-label={playState === 'playing' ? 'Stop' : 'Start'}
191→                >
192→                  {playState === 'playing' ? (
193→                    <svg width="14" height="14" viewBox="0 0 14 14" fill="currentColor">
194→                      <rect x="1" y="1" width="12" height="12" rx="2" />
195→                    </svg>
196→                  ) : (
197→                    <svg width="20" height="20" viewBox="0 0 20 20" fill="currentColor">
198→                      <path d="M5 3.5L16.5 10L5 16.5V3.5Z" />
199→                    </svg>
200→                  )}
201→                </button>
202→                {isActive && (
203→                  <div className="flex items-center gap-1.5">
204→                    <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse" />
205→                    <span className="text-xs text-gray-400 uppercase tracking-wider">Live</span>
206→                  </div>
207→                )}
208→              </div>
209→              <BpmControl />
210→            </div>
211→          </div>
212→
213→          {/* Tap pads */}
214→          <TapPadPanel tapMatcher={tapMatcherRef.current} isActive={isActive} />
215→
216→          {/* Stats */}
217→          <LiveStatsPanel />
218→        </div>
219→
220→        {/* Help text */}
221→        <div className="mt-4 text-center text-xs text-gray-600">
222→          Press the mapped keys to tap along with the beat.
223→          <span className="mx-2">|</span>
224→          <span className="bg-gray-800/50 px-2 py-1 rounded">D</span> Kick
225→          <span className="mx-1">|</span>
226→          <span className="bg-gray-800/50 px-2 py-1 rounded">F</span> Snare
227→          <span className="mx-1">|</span>
228→          <span className="bg-gray-800/50 px-2 py-1 rounded">J</span> Hi-Hat
229→        </div>
230→      </main>
231→
232→      {/* Results modal */}
233→      <LiveResultsModal
234→        isOpen={showResults}
235→        onRetry={handleRetry}
236→        onClose={handleBackToPatterns}
237→      />
238→    </div>
239→  );
240→}
