'use client';

import React from 'react';
import { ALL_NOTES } from '@/lib/sight-reading/notes';
import { NoteHead } from './NoteHead';

interface StaffProps {
  noteIndices: number[];
  currentNoteIndex: number;
  results?: { correct: boolean }[];
}

// Staff dimensions
const STAFF_WIDTH = 600;
const STAFF_HEIGHT = 260;
const STAFF_TOP = 60;       // Y of top staff line
const LINE_SPACING = 14;    // pixels between staff lines
const LEFT_MARGIN = 80;     // space for clef
const NOTE_SPACING = 70;    // horizontal spacing between notes

// Staff line positions (5 lines, top to bottom)
// Treble clef lines from top: F5, D5, B4, G4, E4
const STAFF_LINES = [0, 1, 2, 3, 4].map((i) => STAFF_TOP + i * LINE_SPACING);

// Map staffSlot to Y position
// staffSlot: diatonic steps from C4.
// E4 (staffSlot=2) is on the bottom staff line (STAFF_LINES[4])
// Each diatonic step = LINE_SPACING / 2
function staffSlotToY(staffSlot: number): number {
  // E4 has staffSlot = 2, sits on STAFF_LINES[4]
  // Each step up = LINE_SPACING/2 pixels up
  const e4Y = STAFF_LINES[4]; // bottom line
  return e4Y - (staffSlot - 2) * (LINE_SPACING / 2);
}

// Determine which ledger lines are needed for a note
function getLedgerLines(staffSlot: number): number[] {
  const lines: number[] = [];

  // Ledger lines below staff (below E4, staffSlot < 2)
  // Middle C (C4, staffSlot=0) needs one ledger line
  // B3 (staffSlot=-1) sits just below that ledger line (no extra)
  // A3 (staffSlot=-2) needs the C ledger line
  // etc.
  if (staffSlot <= 0) {
    // Need ledger lines at staffSlot 0 (C4), -2 (A3), -4 (F3), -6 (D3)
    for (let s = 0; s >= staffSlot; s -= 2) {
      lines.push(s);
    }
  }

  // Ledger lines above staff (above F5, staffSlot > 10)
  if (staffSlot >= 12) {
    for (let s = 12; s <= staffSlot; s += 2) {
      lines.push(s);
    }
  }

  return lines;
}

// Treble clef SVG path (simplified)
function TrebleClef() {
  return (
    <text
      x={35}
      y={STAFF_LINES[4] + 10}
      fontSize="72"
      fill="#9ca3af"
      fontFamily="serif"
      style={{ userSelect: 'none' }}
    >
      {'\u{1D11E}'}
    </text>
  );
}

export const Staff = React.memo(function Staff({
  noteIndices,
  currentNoteIndex,
  results,
}: StaffProps) {
  return (
    <svg
      viewBox={`0 0 ${STAFF_WIDTH} ${STAFF_HEIGHT}`}
      className="w-full max-w-[600px]"
      preserveAspectRatio="xMidYMid meet"
    >
      {/* Staff lines */}
      {STAFF_LINES.map((y, i) => (
        <line
          key={i}
          x1={20}
          y1={y}
          x2={STAFF_WIDTH - 20}
          y2={y}
          stroke="#4b5563"
          strokeWidth={1}
        />
      ))}

      {/* Treble clef */}
      <TrebleClef />

      {/* Notes */}
      {noteIndices.map((noteIndex, i) => {
        const note = ALL_NOTES[noteIndex];
        if (!note) return null;

        const x = LEFT_MARGIN + i * NOTE_SPACING + NOTE_SPACING / 2;
        const y = staffSlotToY(note.staffSlot);
        const ledgerSlots = getLedgerLines(note.staffSlot);
        const isCurrent = i === currentNoteIndex;
        const result = results?.[i];

        let color = '#9ca3af'; // default gray
        if (result) {
          color = result.correct ? '#4ade80' : '#f87171'; // green or red
        } else if (isCurrent) {
          color = '#60a5fa'; // blue highlight for current
        }

        return (
          <g key={i}>
            {/* Ledger lines */}
            {ledgerSlots.map((slot) => {
              const ly = staffSlotToY(slot);
              return (
                <line
                  key={`ledger-${slot}`}
                  x1={x - 14}
                  y1={ly}
                  x2={x + 14}
                  y2={ly}
                  stroke="#4b5563"
                  strokeWidth={1}
                />
              );
            })}

            {/* Note head */}
            <NoteHead
              x={x}
              y={y}
              isSharp={note.isSharp}
              color={color}
            />
          </g>
        );
      })}
    </svg>
  );
});

'use client';

import React from 'react';

interface NoteHeadProps {
  x: number;
  y: number;
  isSharp: boolean;
  color: string;
}

export const NoteHead = React.memo(function NoteHead({
  x,
  y,
  isSharp,
  color,
}: NoteHeadProps) {
  return (
    <g>
      {/* Accidental (sharp symbol) */}
      {isSharp && (
        <text
          x={x - 18}
          y={y + 5}
          fontSize="16"
          fill={color}
          fontFamily="serif"
          textAnchor="middle"
          style={{ userSelect: 'none' }}
        >
          ♯
        </text>
      )}

      {/* Filled note head (quarter note style) */}
      <ellipse
        cx={x}
        cy={y}
        rx={7}
        ry={5}
        fill={color}
        transform={`rotate(-10, ${x}, ${y})`}
      />

      {/* Stem */}
      <line
        x1={x + 6.5}
        y1={y}
        x2={x + 6.5}
        y2={y - 30}
        stroke={color}
        strokeWidth={1.5}
      />
    </g>
  );
});

'use client';

import React, { useCallback } from 'react';
import { ALL_NOTES } from '@/lib/sight-reading/notes';

interface PianoKeyboardProps {
  onNotePlay: (noteIndex: number) => void;
  activeNote: number | null;
}

// White key indices in our 24-note range (C3-B4)
const WHITE_KEY_INDICES = ALL_NOTES
  .filter((n) => !n.isSharp)
  .map((n) => n.index);

// Black key info: position relative to previous white key
interface BlackKeyInfo {
  noteIndex: number;
  leftWhiteIndex: number; // index of the white key to the left
}

const BLACK_KEY_INFOS: BlackKeyInfo[] = ALL_NOTES
  .filter((n) => n.isSharp)
  .map((n) => ({
    noteIndex: n.index,
    leftWhiteIndex: n.index - 1, // sharp is always 1 semitone above the natural
  }));

const WHITE_KEY_WIDTH = 36;
const WHITE_KEY_HEIGHT = 140;
const BLACK_KEY_WIDTH = 22;
const BLACK_KEY_HEIGHT = 88;

export const PianoKeyboard = React.memo(function PianoKeyboard({
  onNotePlay,
  activeNote,
}: PianoKeyboardProps) {
  const handleWhiteKey = useCallback(
    (noteIndex: number) => (e: React.MouseEvent | React.TouchEvent) => {
      e.preventDefault();
      onNotePlay(noteIndex);
    },
    [onNotePlay]
  );

  const handleBlackKey = useCallback(
    (noteIndex: number) => (e: React.MouseEvent | React.TouchEvent) => {
      e.preventDefault();
      e.stopPropagation();
      onNotePlay(noteIndex);
    },
    [onNotePlay]
  );

  const totalWidth = WHITE_KEY_INDICES.length * WHITE_KEY_WIDTH;

  // Build a map of white key index → x position
  const whiteKeyPositions = new Map<number, number>();
  WHITE_KEY_INDICES.forEach((noteIndex, i) => {
    whiteKeyPositions.set(noteIndex, i * WHITE_KEY_WIDTH);
  });

  return (
    <div className="relative select-none overflow-x-auto">
      <div
        className="relative mx-auto"
        style={{ width: totalWidth, height: WHITE_KEY_HEIGHT }}
      >
        {/* White keys */}
        {WHITE_KEY_INDICES.map((noteIndex, i) => {
          const note = ALL_NOTES[noteIndex];
          const x = i * WHITE_KEY_WIDTH;
          const isActive = activeNote === noteIndex;

          return (
            <button
              key={noteIndex}
              onMouseDown={handleWhiteKey(noteIndex)}
              onTouchStart={handleWhiteKey(noteIndex)}
              className="absolute border border-gray-600 rounded-b-md transition-colors duration-75 cursor-pointer"
              style={{
                left: x,
                top: 0,
                width: WHITE_KEY_WIDTH - 1,
                height: WHITE_KEY_HEIGHT,
                backgroundColor: isActive ? '#60a5fa' : '#e5e7eb',
                zIndex: 1,
              }}
            >
              <span className="absolute bottom-2 left-1/2 -translate-x-1/2 text-[10px] text-gray-500 font-medium">
                {note.name}
              </span>
              <span className="absolute bottom-7 left-1/2 -translate-x-1/2 text-[9px] text-gray-400 uppercase">
                {note.keyboardKey}
              </span>
            </button>
          );
        })}

        {/* Black keys */}
        {BLACK_KEY_INFOS.map(({ noteIndex, leftWhiteIndex }) => {
          const leftWhiteX = whiteKeyPositions.get(leftWhiteIndex);
          if (leftWhiteX === undefined) return null;

          const note = ALL_NOTES[noteIndex];
          const x = leftWhiteX + WHITE_KEY_WIDTH - BLACK_KEY_WIDTH / 2;
          const isActive = activeNote === noteIndex;

          return (
            <button
              key={noteIndex}
              onMouseDown={handleBlackKey(noteIndex)}
              onTouchStart={handleBlackKey(noteIndex)}
              className="absolute rounded-b-md transition-colors duration-75 cursor-pointer"
              style={{
                left: x,
                top: 0,
                width: BLACK_KEY_WIDTH,
                height: BLACK_KEY_HEIGHT,
                backgroundColor: isActive ? '#3b82f6' : '#1f2937',
                zIndex: 2,
              }}
            >
              <span className="absolute bottom-2 left-1/2 -translate-x-1/2 text-[8px] text-gray-400 font-medium">
                {note.keyboardKey}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
});

