'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';

const nav = [
  { href: '/', label: 'Patterns' },
  { href: '/practice', label: 'Practice' },
  { href: '/live', label: 'Live' },
];

export function Header() {
