199→                    </svg>
200→                  )}
201→                </button>
202→                {isActive && (
203→                  <div className="flex items-center gap-1.5">
204→                    <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse" />
205→                    <span className="text-xs text-gray-400 uppercase tracking-wider">Live</span>
206→                  </div>
