 1→import { create } from 'zustand';
 2→import { DrumPattern } from '../patterns/types';
 3→import { basicRockBeat } from '../patterns/rock';
 4→import { allPatterns } from '../patterns';
 5→import { clonePattern } from '../patterns/utils';
 6→
 7→interface PatternStore {
 8→  currentPattern: DrumPattern;
 9→  isModified: boolean;
10→
11→  loadPattern: (pattern: DrumPattern) => void;
12→  toggleStep: (trackIndex: number, stepIndex: number) => void;
13→  setTrackVolume: (trackIndex: number, volume: number) => void;
14→  toggleTrackMute: (trackIndex: number) => void;
15→  resetPattern: () => void;
16→}
17→
18→export const usePatternStore = create<PatternStore>((set, get) => ({
19→  currentPattern: clonePattern(basicRockBeat),
20→  isModified: false,
21→
22→  loadPattern: (pattern: DrumPattern) => {
23→    set({ currentPattern: clonePattern(pattern), isModified: false });
24→  },
25→
26→  toggleStep: (trackIndex: number, stepIndex: number) => {
27→    const pattern = clonePattern(get().currentPattern);
28→    const step = pattern.tracks[trackIndex].steps[stepIndex];
29→    step.active = !step.active;
30→    set({ currentPattern: pattern, isModified: true });
31→  },
32→
33→  setTrackVolume: (trackIndex: number, volume: number) => {
34→    const pattern = clonePattern(get().currentPattern);
35→    pattern.tracks[trackIndex].volume = volume;
36→    set({ currentPattern: pattern });
37→  },
38→
39→  toggleTrackMute: (trackIndex: number) => {
40→    const pattern = clonePattern(get().currentPattern);
41→    pattern.tracks[trackIndex].muted = !pattern.tracks[trackIndex].muted;
42→    set({ currentPattern: pattern });
43→  },
44→
45→  resetPattern: () => {
46→    const original = allPatterns.find(
47→      (p: DrumPattern) => p.id === get().currentPattern.id
48→    );
49→    if (original) {
50→      set({ currentPattern: clonePattern(original), isModified: false });
51→    }
52→  },
53→}));
