22→  processTap(tapTime: number, instrumentId: InstrumentId): TapEvent {
23→    let bestBeat: ExpectedBeat | null = null;
24→    let bestAbsOffset = Infinity;
25→
26→    for (const beat of this.expectedBeats) {
27→      if (beat.matched || beat.instrumentId !== instrumentId) continue;
28→      const absOffset = Math.abs(tapTime - beat.time);
29→      if (absOffset < bestAbsOffset) {
30→        bestAbsOffset = absOffset;
31→        bestBeat = beat;
32→      }
33→    }
34→
35→    let grade: TimingGrade;
36→    let matchedStep: number | null = null;
37→    let offset = 0;
38→
39→    if (bestBeat && bestAbsOffset <= TIMING_THRESHOLDS.MAX_WINDOW) {
40→      bestBeat.matched = true;
41→      matchedStep = bestBeat.step;
42→      offset = tapTime - bestBeat.time;
43→
44→      if (bestAbsOffset <= TIMING_THRESHOLDS.PERFECT) grade = 'perfect';
45→      else if (bestAbsOffset <= TIMING_THRESHOLDS.GREAT) grade = 'great';
46→      else if (bestAbsOffset <= TIMING_THRESHOLDS.GOOD) grade = 'good';
47→      else grade = offset < 0 ? 'early' : 'late';
48→    } else {
