50→      grade = 'early';
51→      offset = 0;
52→    }
53→
54→    const tap: TapEvent = {
55→      timestamp: tapTime,
56→      instrumentId,
57→      matchedStep,
58→      offset,
59→      grade,
60→    };
61→    this.taps.push(tap);
