  const currentBpm = useTransportStore.getState().bpm;

  if (finalStats.totalExpected > 0) {
    const accuracy = Math.round((finalStats.totalHits / finalStats.totalExpected) * 100);

    addSession({
      patternId: currentPattern.id,
      patternName: currentPattern.name,
      mode: 'live',
      startedAt: sessionStartRef.current,   // see note below
      endedAt: sessionEndTime,
      durationMs: sessionEndTime - sessionStartRef.current,
      bpm: currentBpm,
      accuracy,
      stats: finalStats,
    });

    updateCard(currentPattern.id, accuracy);
    setShowResults(true);
  }
}, [stop, endSession, addSession, updateCard]);
