## 5. The `usePracticeHistoryStore` Implementation Detail

```typescript
import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { allPatterns } from '../patterns';
import { computeNextReview, accuracyToQuality, isCardDue } from '../spaced-repetition/sm2';

const MAX_SESSIONS = 2000;   // ~400KB at 200 bytes/session

export const usePracticeHistoryStore = create<PracticeHistoryState>()(
  persist(
    (set, get) => ({
      sessions: [],
      cards: {},

      addSession: (sessionData) => {
        const session: PracticeSession = {
          ...sessionData,
          id: crypto.randomUUID(),
        };
        set((state) => {
          const sessions = [session, ...state.sessions];  // newest first
          // Trim if over limit
          return { sessions: sessions.slice(0, MAX_SESSIONS) };
        });
      },

      updateCard: (patternId, accuracy) => {
        const existing = get().cards[patternId];
        const current = existing ?? {
          easeFactor: 2.5,
          intervalDays: 1,
          repetitions: 0,
        };
        const quality = accuracyToQuality(accuracy);
        const result = computeNextReview(current, quality);

        set((state) => ({
          cards: {
            ...state.cards,
            [patternId]: {
              patternId,
              easeFactor: result.easeFactor,
              intervalDays: result.intervalDays,
              repetitions: result.repetitions,
              lastReviewedAt: Date.now(),
              nextReviewAt: result.nextReviewAt,
              lastAccuracy: accuracy,
            },
          },
        }));
      },

      clearHistory: () => set({ sessions: [], cards: {} }),

      getSessionsForPattern: (patternId) =>
        get().sessions.filter((s) => s.patternId === patternId),

      getCardForPattern: (patternId) =>
        get().cards[patternId],

      getDuePatterns: () => {
        const { cards } = get();
        const now = Date.now();

        // Patterns with cards that are due
        const due = Object.values(cards)
          .filter((card) => isCardDue(card))
          .sort((a, b) => {
            // Sort overdue by how overdue (oldest first), new patterns (null) last
            if (a.nextReviewAt === null) return 1;
            if (b.nextReviewAt === null) return -1;
            return a.nextReviewAt - b.nextReviewAt;
          })
          .map((card) => card.patternId);

        // Patterns with no card at all (never practiced in live mode)
        const practiced = new Set(Object.keys(cards));
        const neverPracticed = allPatterns
          .filter((p) => !practiced.has(p.id))
          .map((p) => p.id);

        return [...due, ...neverPracticed];
      },

      getTotalPracticeMs: () =>
        get().sessions.reduce((sum, s) => sum + s.durationMs, 0),

      getPracticedDays: () => {
        const days = new Set<string>();
        get().sessions.forEach((s) => {
          const d = new Date(s.startedAt);
          days.add(`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`);
        });
        return days;
      },
    }),
    { name: 'drum-practice-history' }
  )
);
```

**One important detail**: `getDuePatterns`, `getTotalPracticeMs`, and `getPracticedDays` are functions stored in Zustand state. This is unusual — typically these would be computed in components. However, since they derive from store data and are used across multiple components, storing them as store methods (which always call `get()` for fresh data) is cleaner than importing a utility function that takes store state as a parameter. React components should call them inside `useCallback` or `useMemo` if performance matters, e.g.:

```typescript
const duePatterns = usePracticeHistoryStore((s) => s.getDuePatterns());
```

Zustand's selector memo system handles re-renders correctly here since `getDuePatterns` is a stable function reference (it's set once at store creation, not on each render).

