'use client';

import React from 'react';

interface PatternAccuracySparklineProps {
  values: number[]; // accuracy percentages (0-100), most recent last
  width?: number;
  height?: number;
}

export const PatternAccuracySparkline = React.memo(function PatternAccuracySparkline({
  values,
  width = 80,
  height = 28,
}: PatternAccuracySparklineProps) {
  if (values.length === 0) return null;

  const padding = 2;
  const innerW = width - padding * 2;
  const innerH = height - padding * 2;

  if (values.length === 1) {
    // Single point — draw a dot
    const y = padding + innerH - (values[0] / 100) * innerH;
    return (
      <svg width={width} height={height} className="block">
        <circle cx={width / 2} cy={y} r={2.5} fill="#4ade80" />
      </svg>
    );
  }

  const points = values.map((v, i) => {
    const x = padding + (i / (values.length - 1)) * innerW;
    const y = padding + innerH - (v / 100) * innerH;
    return `${x},${y}`;
  });

  const lastX = padding + innerW;
  const lastY = padding + innerH - (values[values.length - 1] / 100) * innerH;

  return (
    <svg width={width} height={height} className="block">
      <polyline
        points={points.join(' ')}
        fill="none"
        stroke="#4ade80"
        strokeWidth={1.5}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <circle cx={lastX} cy={lastY} r={2} fill="#4ade80" />
    </svg>
  );
});

'use client';

import { usePracticeHistoryStore, getTotalPracticeMs, getPracticedDays } from '@/lib/store/usePracticeHistoryStore';

function formatDuration(ms: number): string {
  const hours = Math.floor(ms / 3_600_000);
  const minutes = Math.floor((ms % 3_600_000) / 60_000);
  if (hours > 0) return `${hours}h ${minutes}m`;
  return `${minutes}m`;
}

function computeStreak(practicedDays: Set<string>): number {
  let streak = 0;
  const today = new Date();
  for (let i = 0; i < 365; i++) {
    const d = new Date(today);
    d.setDate(today.getDate() - i);
    const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    if (practicedDays.has(key)) streak++;
    else break;
  }
  return streak;
}

export function OverallStatsRow() {
  const sessions = usePracticeHistoryStore((s) => s.sessions);

  const totalMs = getTotalPracticeMs();
  const days = getPracticedDays();
  const streak = computeStreak(days);
  const uniquePatterns = new Set(sessions.map((s) => s.patternId)).size;

  const tiles = [
    { label: 'Total Time', value: sessions.length > 0 ? formatDuration(totalMs) : '--' },
    { label: 'Sessions', value: sessions.length.toString() },
    { label: 'Patterns', value: uniquePatterns.toString() },
    { label: 'Day Streak', value: streak > 0 ? `${streak}d` : '--' },
  ];

  return (
    <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
      {tiles.map((tile) => (
        <div
          key={tile.label}
          className="bg-[#1a1d27] rounded-xl p-4 border border-gray-800 text-center"
        >
          <div className="text-2xl font-bold text-white">{tile.value}</div>
          <div className="text-xs text-gray-500 mt-1">{tile.label}</div>
        </div>
      ))}
    </div>
  );
}

'use client';

import { usePracticeHistoryStore } from '@/lib/store/usePracticeHistoryStore';

function dateToKey(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

function getIntensityClass(minutesPracticed: number): string {
  if (minutesPracticed === 0) return 'bg-gray-800';
  if (minutesPracticed < 5) return 'bg-green-900';
  if (minutesPracticed < 15) return 'bg-green-700';
  return 'bg-green-500';
}

const DAY_LABELS = ['', 'Mon', '', 'Wed', '', 'Fri', ''];

export function PracticeCalendar() {
  const sessions = usePracticeHistoryStore((s) => s.sessions);

  // Build daily totals
  const dailyMinutes = new Map<string, number>();
  sessions.forEach((s) => {
    const key = dateToKey(new Date(s.startedAt));
    dailyMinutes.set(key, (dailyMinutes.get(key) ?? 0) + s.durationMs / 60_000);
  });

  // Generate 12 weeks of dates ending today
  const today = new Date();
  const cells: { date: Date; key: string }[] = [];

  // Start from 83 days ago (12 weeks - 1)
  const startDate = new Date(today);
  startDate.setDate(today.getDate() - 83);
  // Adjust to Monday
  const dayOfWeek = startDate.getDay();
  const mondayOffset = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
  startDate.setDate(startDate.getDate() + mondayOffset);

  for (let i = 0; i < 84; i++) {
    const d = new Date(startDate);
    d.setDate(startDate.getDate() + i);
    cells.push({ date: d, key: dateToKey(d) });
  }

  return (
    <div className="bg-[#1a1d27] rounded-xl p-4 border border-gray-800">
      <h3 className="text-sm font-medium text-gray-400 mb-3">Practice Calendar</h3>
      <div className="flex gap-1">
        {/* Day labels */}
        <div className="flex flex-col gap-1 mr-1">
          {DAY_LABELS.map((label, i) => (
            <div key={i} className="w-6 h-3 text-[9px] text-gray-600 flex items-center">
              {label}
            </div>
          ))}
        </div>

        {/* Grid: 12 columns (weeks) x 7 rows (days) */}
        <div className="grid grid-rows-7 grid-flow-col gap-1">
          {cells.map((cell) => {
            const minutes = dailyMinutes.get(cell.key) ?? 0;
            const isFuture = cell.date > today;
            return (
              <div
                key={cell.key}
                className={`w-3 h-3 rounded-sm ${isFuture ? 'bg-gray-900' : getIntensityClass(minutes)}`}
                title={`${cell.key}: ${minutes > 0 ? `${Math.round(minutes)}min` : 'No practice'}`}
              />
            );
          })}
        </div>
      </div>

      <div className="flex items-center gap-2 mt-3 text-[9px] text-gray-600">
        <span>Less</span>
        <div className="w-3 h-3 rounded-sm bg-gray-800" />
        <div className="w-3 h-3 rounded-sm bg-green-900" />
        <div className="w-3 h-3 rounded-sm bg-green-700" />
        <div className="w-3 h-3 rounded-sm bg-green-500" />
        <span>More</span>
      </div>
    </div>
  );
}

'use client';

import { useRouter } from 'next/navigation';
import { getDuePatterns, usePracticeHistoryStore } from '@/lib/store/usePracticeHistoryStore';
import { usePatternStore } from '@/lib/store/usePatternStore';
import { useTransportStore } from '@/lib/store/useTransportStore';
import { allPatterns } from '@/lib/patterns';
import { getMasteryLevel, getMasteryColor } from '@/lib/spaced-repetition/sm2';

export function DueForReviewSection() {
  const cards = usePracticeHistoryStore((s) => s.cards);
  const loadPattern = usePatternStore((s) => s.loadPattern);
  const setBpm = useTransportStore((s) => s.setBpm);
  const stop = useTransportStore((s) => s.stop);
  const router = useRouter();

  const dueIds = getDuePatterns();
  const duePatterns = dueIds
    .map((id) => allPatterns.find((p) => p.id === id))
    .filter(Boolean)
    .slice(0, 10); // Show at most 10

  if (duePatterns.length === 0) {
    return (
      <div className="bg-[#1a1d27] rounded-xl p-4 border border-gray-800 text-center text-sm text-gray-500">
        All caught up! No patterns due for review.
      </div>
    );
  }

  const handlePractice = (patternId: string) => {
    const pattern = allPatterns.find((p) => p.id === patternId);
    if (!pattern) return;
    stop();
    loadPattern(pattern);
    setBpm(pattern.defaultBpm);
    router.push('/live');
  };

  return (
    <div className="bg-[#1a1d27] rounded-xl p-4 border border-gray-800">
      <h3 className="text-sm font-medium text-gray-400 mb-3">
        Due for Review ({dueIds.length})
      </h3>
      <div className="flex gap-3 overflow-x-auto pb-1">
        {duePatterns.map((pattern) => {
          if (!pattern) return null;
          const card = cards[pattern.id];
          const reps = card?.repetitions ?? 0;
          const lastAcc = card?.lastAccuracy;
          const daysOverdue = card?.nextReviewAt
            ? Math.max(0, Math.floor((Date.now() - card.nextReviewAt) / 86_400_000))
            : null;

          return (
            <button
              key={pattern.id}
              onClick={() => handlePractice(pattern.id)}
              className="flex-shrink-0 w-44 bg-gray-800/50 rounded-lg p-3 border border-gray-700
                         hover:border-gray-500 transition-colors cursor-pointer text-left"
            >
              <div className="flex items-start justify-between mb-1">
                <span className="text-xs font-medium text-gray-200 truncate">
                  {pattern.name}
                </span>
              </div>
              <div className="flex items-center gap-1.5 mb-2">
                <span className={`text-[10px] px-1.5 py-0.5 rounded-full ${getMasteryColor(reps)}`}>
                  {getMasteryLevel(reps)}
                </span>
                {daysOverdue !== null && daysOverdue > 0 && (
                  <span className="text-[10px] text-orange-400">
                    {daysOverdue}d overdue
                  </span>
                )}
              </div>
              {lastAcc !== null && lastAcc !== undefined && (
                <div className="text-xs text-gray-500">
                  Last: {lastAcc}%
                </div>
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
}

