 1→import { InstrumentId } from '../patterns/types';
 2→import {
 3→  ExpectedBeat,
 4→  TapEvent,
 5→  TimingGrade,
 6→  TIMING_THRESHOLDS,
 7→} from './types';
 8→
 9→export class TapMatcher {
10→  private expectedBeats: ExpectedBeat[] = [];
11→  private taps: TapEvent[] = [];
12→
13→  reset(): void {
14→    this.expectedBeats = [];
15→    this.taps = [];
16→  }
17→
18→  addExpectedBeat(step: number, time: number, instrumentId: InstrumentId): void {
19→    this.expectedBeats.push({ step, time, instrumentId, matched: false });
20→  }
21→
22→  processTap(tapTime: number, instrumentId: InstrumentId): TapEvent {
23→    let bestBeat: ExpectedBeat | null = null;
24→    let bestAbsOffset = Infinity;
25→
26→    for (const beat of this.expectedBeats) {
27→      if (beat.matched || beat.instrumentId !== instrumentId) continue;
28→      const absOffset = Math.abs(tapTime - beat.time);
29→      if (absOffset < bestAbsOffset) {
30→        bestAbsOffset = absOffset;
31→        bestBeat = beat;
32→      }
33→    }
34→
35→    let grade: TimingGrade;
36→    let matchedStep: number | null = null;
37→    let offset = 0;
38→
39→    if (bestBeat && bestAbsOffset <= TIMING_THRESHOLDS.MAX_WINDOW) {
40→      bestBeat.matched = true;
41→      matchedStep = bestBeat.step;
42→      offset = tapTime - bestBeat.time;
43→
44→      if (bestAbsOffset <= TIMING_THRESHOLDS.PERFECT) grade = 'perfect';
45→      else if (bestAbsOffset <= TIMING_THRESHOLDS.GREAT) grade = 'great';
46→      else if (bestAbsOffset <= TIMING_THRESHOLDS.GOOD) grade = 'good';
47→      else grade = offset < 0 ? 'early' : 'late';
48→    } else {
49→      // Stray tap — no matching beat nearby
50→      grade = 'early';
51→      offset = 0;
52→    }
53→
54→    const tap: TapEvent = {
55→      timestamp: tapTime,
56→      instrumentId,
57→      matchedStep,
58→      offset,
59→      grade,
60→    };
61→    this.taps.push(tap);
62→    return tap;
63→  }
64→
65→  sweepMisses(currentTime: number): ExpectedBeat[] {
66→    const missThreshold = currentTime - TIMING_THRESHOLDS.MAX_WINDOW;
67→    const misses: ExpectedBeat[] = [];
68→
69→    this.expectedBeats = this.expectedBeats.filter((beat) => {
70→      if (!beat.matched && beat.time < missThreshold) {
71→        misses.push(beat);
72→        return false;
73→      }
74→      if (beat.matched && beat.time < missThreshold) {
75→        return false;
76→      }
77→      return true;
78→    });
79→
80→    return misses;
81→  }
82→
83→  getTaps(): TapEvent[] {
84→    return this.taps;
85→  }
86→}
