 5→function formatDuration(ms: number): string {
 6→  const hours = Math.floor(ms / 3_600_000);
 7→  const minutes = Math.floor((ms % 3_600_000) / 60_000);
 8→  if (hours > 0) return `${hours}h ${minutes}m`;
 9→  return `${minutes}m`;
10→}
11→
12→function computeStreak(practicedDays: Set<string>): number {
13→  let streak = 0;
14→  const today = new Date();
15→  for (let i = 0; i < 365; i++) {
16→    const d = new Date(today);
17→    d.setDate(today.getDate() - i);
18→    const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
19→    if (practicedDays.has(key)) streak++;
20→    else break;
21→  }
22→  return streak;
23→}
