 1→'use client';
 2→
 3→import React from 'react';
 4→
 5→interface PatternAccuracySparklineProps {
 6→  values: number[]; // accuracy percentages (0-100), most recent last
 7→  width?: number;
 8→  height?: number;
 9→}
10→
11→export const PatternAccuracySparkline = React.memo(function PatternAccuracySparkline({
12→  values,
13→  width = 80,
14→  height = 28,
15→}: PatternAccuracySparklineProps) {
16→  if (values.length === 0) return null;
17→
18→  const padding = 2;
19→  const innerW = width - padding * 2;
20→  const innerH = height - padding * 2;
21→
22→  if (values.length === 1) {
23→    // Single point — draw a dot
24→    const y = padding + innerH - (values[0] / 100) * innerH;
25→    return (
26→      <svg width={width} height={height} className="block">
27→        <circle cx={width / 2} cy={y} r={2.5} fill="#4ade80" />
28→      </svg>
29→    );
30→  }
31→
32→  const points = values.map((v, i) => {
33→    const x = padding + (i / (values.length - 1)) * innerW;
34→    const y = padding + innerH - (v / 100) * innerH;
35→    return `${x},${y}`;
36→  });
37→
38→  const lastX = padding + innerW;
39→  const lastY = padding + innerH - (values[values.length - 1] / 100) * innerH;
40→
41→  return (
42→    <svg width={width} height={height} className="block">
43→      <polyline
44→        points={points.join(' ')}
45→        fill="none"
46→        stroke="#4ade80"
47→        strokeWidth={1.5}
48→        strokeLinecap="round"
49→        strokeLinejoin="round"
50→      />
51→      <circle cx={lastX} cy={lastY} r={2} fill="#4ade80" />
52→    </svg>
53→  );
54→});
