 9→function getIntensityClass(minutesPracticed: number): string {
10→  if (minutesPracticed === 0) return 'bg-gray-800';
11→  if (minutesPracticed < 5) return 'bg-green-900';
12→  if (minutesPracticed < 15) return 'bg-green-700';
