18→export function PracticeCalendar() {
19→  const sessions = usePracticeHistoryStore((s) => s.sessions);
20→
21→  // Build daily totals
22→  const dailyMinutes = new Map<string, number>();
23→  sessions.forEach((s) => {
24→    const key = dateToKey(new Date(s.startedAt));
25→    dailyMinutes.set(key, (dailyMinutes.get(key) ?? 0) + s.durationMs / 60_000);
26→  });
27→
28→  // Generate 12 weeks of dates ending today
29→  const today = new Date();
30→  const cells: { date: Date; key: string }[] = [];
31→
32→  // Start from 83 days ago (12 weeks - 1)
33→  const startDate = new Date(today);
34→  startDate.setDate(today.getDate() - 83);
35→  // Adjust to Monday
36→  const dayOfWeek = startDate.getDay();
37→  const mondayOffset = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
38→  startDate.setDate(startDate.getDate() + mondayOffset);
39→
40→  for (let i = 0; i < 84; i++) {
41→    const d = new Date(startDate);
42→    d.setDate(startDate.getDate() + i);
43→    cells.push({ date: d, key: dateToKey(d) });
44→  }
