64→            return (
65→              <div
66→                key={cell.key}
67→                className={`w-3 h-3 rounded-sm ${isFuture ? 'bg-gray-900' : getIntensityClass(minutes)}`}
68→                title={`${cell.key}: ${minutes > 0 ? `${Math.round(minutes)}min` : 'No practice'}`}
69→              />
