130→export function getPracticedDays(): Set<string> {
131→  const days = new Set<string>();
132→  usePracticeHistoryStore.getState().sessions.forEach((s) => {
133→    const d = new Date(s.startedAt);
134→    days.add(
135→      `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
136→    );
137→  });
138→  return days;
139→}
