  1→/**
  2→ * SM-2 Spaced Repetition Algorithm adapted for drum practice.
  3→ *
  4→ * Based on the SuperMemo SM-2 algorithm by Piotr Wozniak.
  5→ * Adapted: accuracy % maps to quality 0-5, interval capped at 365 days.
  6→ */
  7→
  8→export interface SM2Input {
  9→  easeFactor: number;
 10→  intervalDays: number;
 11→  repetitions: number;
 12→}
 13→
 14→export interface SM2Result {
 15→  easeFactor: number;
 16→  intervalDays: number;
 17→  repetitions: number;
 18→  nextReviewAt: number; // ms timestamp
 19→}
 20→
 21→/**
 22→ * Map accuracy percentage (0-100) to SM-2 quality rating (0-5).
 23→ */
 24→export function accuracyToQuality(accuracy: number): number {
 25→  if (accuracy >= 95) return 5;
 26→  if (accuracy >= 85) return 4;
 27→  if (accuracy >= 70) return 3;
 28→  if (accuracy >= 50) return 2;
 29→  if (accuracy >= 30) return 1;
 30→  return 0;
 31→}
 32→
 33→const MIN_EASE = 1.3;
 34→const MAX_INTERVAL_DAYS = 365;
 35→
 36→/**
 37→ * Compute the next review schedule using SM-2.
 38→ *
 39→ * quality >= 3: success — advance interval
 40→ * quality < 3: failure — reset to 1 day
 41→ */
 42→export function computeNextReview(
 43→  current: SM2Input,
 44→  quality: number
 45→): SM2Result {
 46→  let { easeFactor, intervalDays, repetitions } = current;
 47→
 48→  if (quality < 3) {
 49→    // Failure: reset
 50→    repetitions = 0;
 51→    intervalDays = 1;
 52→    easeFactor = Math.max(MIN_EASE, easeFactor - 0.2);
 53→  } else {
 54→    // Success
 55→    if (repetitions === 0) {
 56→      intervalDays = 1;
 57→    } else if (repetitions === 1) {
 58→      intervalDays = 6;
 59→    } else {
 60→      intervalDays = Math.round(intervalDays * easeFactor);
 61→    }
 62→
 63→    // SM-2 ease factor adjustment
 64→    easeFactor = Math.max(
 65→      MIN_EASE,
 66→      easeFactor + (0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02))
 67→    );
 68→
 69→    repetitions += 1;
 70→  }
 71→
 72→  intervalDays = Math.min(intervalDays, MAX_INTERVAL_DAYS);
 73→
 74→  const nextReviewAt = Date.now() + intervalDays * 24 * 60 * 60 * 1000;
 75→
 76→  return { easeFactor, intervalDays, repetitions, nextReviewAt };
 77→}
 78→
 79→export interface SpacedRepCard {
 80→  patternId: string;
 81→  easeFactor: number;
 82→  intervalDays: number;
 83→  repetitions: number;
 84→  lastReviewedAt: number | null;
 85→  nextReviewAt: number | null;
 86→  lastAccuracy: number | null;
 87→}
 88→
 89→/**
 90→ * Check if a card is due for review (or has never been reviewed).
 91→ */
 92→export function isCardDue(card: SpacedRepCard): boolean {
 93→  if (card.nextReviewAt === null) return true;
 94→  return card.nextReviewAt <= Date.now();
 95→}
 96→
 97→/**
 98→ * Get a human-readable mastery level from repetition count.
 99→ */
100→export function getMasteryLevel(repetitions: number): string {

100→export function getMasteryLevel(repetitions: number): string {
101→  if (repetitions === 0) return 'New';
102→  if (repetitions <= 2) return 'Learning';
103→  if (repetitions <= 5) return 'Familiar';
104→  return 'Mastered';
105→}
106→
107→export function getMasteryColor(repetitions: number): string {
108→  if (repetitions === 0) return 'bg-gray-700 text-gray-300';
109→  if (repetitions <= 2) return 'bg-yellow-900 text-yellow-300';
110→  if (repetitions <= 5) return 'bg-blue-900 text-blue-300';
111→  return 'bg-green-900 text-green-300';
112→}
