 6→import { useLivePracticeStore } from '../store/useLivePracticeStore';
 7→import { TapMatcher } from '../live-practice/TapMatcher';
 8→
 9→export function useLiveKeyboardHandler(
10→  tapMatcher: TapMatcher | null,
11→  isActive: boolean
12→) {
13→  useEffect(() => {
14→    if (!isActive || !tapMatcher) return;
15→
16→    const handleKeyDown = (e: KeyboardEvent) => {
17→      if (e.repeat) return;
18→      if (
19→        e.target instanceof HTMLInputElement ||
20→        e.target instanceof HTMLTextAreaElement
21→      ) {
22→        return;
23→      }
24→
25→      const { keyMappings } = useLivePracticeStore.getState();
26→      const mapping = keyMappings.find((m) => m.key === e.code);
27→      if (!mapping) return;
28→
29→      e.preventDefault();
30→
31→      const tapTime = audioEngine.currentTime;
32→
33→      // Immediate audio feedback
34→      playInstrument(mapping.instrumentId, tapTime, 0.8, 0.8);
35→
36→      // Process tap through matcher
37→      const tapEvent = tapMatcher.processTap(tapTime, mapping.instrumentId);
38→
39→      // Update store
40→      const store = useLivePracticeStore.getState();
41→      store.recordTap(tapEvent);
42→      if (tapEvent.matchedStep !== null) {
43→        store.setStepAccuracy(
44→          tapEvent.matchedStep,
45→          mapping.instrumentId,
46→          tapEvent.grade,
47→          tapEvent.offset
48→        );
49→      }
50→    };
51→
52→    window.addEventListener('keydown', handleKeyDown);
53→    return () => window.removeEventListener('keydown', handleKeyDown);
54→  }, [isActive, tapMatcher]);
55→}
