 22→
 23→export default function LivePracticePage() {
 24→  const pattern = usePatternStore((s) => s.currentPattern);
 25→  const playState = useTransportStore((s) => s.playState);
 26→  const play = useTransportStore((s) => s.play);
 27→  const stop = useTransportStore((s) => s.stop);
 28→  const bpm = useTransportStore((s) => s.bpm);
 29→
 30→  const isActive = useLivePracticeStore((s) => s.isActive);
 31→  const startSession = useLivePracticeStore((s) => s.startSession);
 32→  const endSession = useLivePracticeStore((s) => s.endSession);
 33→  const mode = useLivePracticeStore((s) => s.mode);
 34→  const focusedTrack = useLivePracticeStore((s) => s.focusedTrack);
 35→  const stepAccuraciesRaw = useLivePracticeStore((s) => s.stepAccuracies);
 36→  const recordMiss = useLivePracticeStore((s) => s.recordMiss);
 37→  const resetStepAccuracies = useLivePracticeStore((s) => s.resetStepAccuracies);
 38→  const stats = useLivePracticeStore((s) => s.stats);
 39→
 40→  const addHistorySession = usePracticeHistoryStore((s) => s.addSession);
 41→  const updateCard = usePracticeHistoryStore((s) => s.updateCard);
 42→
 43→  const [showResults, setShowResults] = useState(false);
 44→
 45→  const tapMatcherRef = useRef<TapMatcher | null>(null);
 46→  const sweepIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
 47→  const sessionStartRef = useRef<number>(0);
 48→
 49→  // Initialize TapMatcher
 50→  if (!tapMatcherRef.current) {
 51→    tapMatcherRef.current = new TapMatcher();
 52→  }
 53→
 54→  // Convert stepAccuracies to the format BeatGrid expects: Record<string, TimingGrade>
 55→  const stepAccuracies = useMemo(() => {
 56→    const result: Record<string, TimingGrade> = {};
 57→    for (const [key, acc] of Object.entries(stepAccuraciesRaw)) {
 58→      result[key] = acc.grade;
 59→    }
 60→    return result;
 61→  }, [stepAccuraciesRaw]);
 62→
 63→  // Register step listener for feeding expected beats to TapMatcher
 64→  useEffect(() => {
 65→    const unsubscribe = scheduler.addStepListener((step, time) => {
 66→      const tapMatcher = tapMatcherRef.current;
 67→      if (!tapMatcher || !useLivePracticeStore.getState().isActive) return;
 68→
 69→      const liveMode = useLivePracticeStore.getState().mode;
 70→      const focused = useLivePracticeStore.getState().focusedTrack;
 71→      const currentPattern = usePatternStore.getState().currentPattern;
 72→
 73→      currentPattern.tracks.forEach((track: Track) => {
 74→        const s = track.steps[step];
 75→        if (!s || !s.active) return;
 76→
 77→        // In single-track mode, only expect beats for the focused instrument
 78→        if (liveMode === 'single-track' && focused && track.instrumentId !== focused) return;
 79→
 80→        tapMatcher.addExpectedBeat(step, time, track.instrumentId);
 81→      });
 82→    });
 83→
 84→    return unsubscribe;
 85→  }, []);
 86→
 87→  // Sweep for misses periodically
 88→  useEffect(() => {
 89→    if (isActive) {
 90→      sweepIntervalRef.current = setInterval(() => {
 91→        const tapMatcher = tapMatcherRef.current;
 92→        if (!tapMatcher) return;
 93→        const misses = tapMatcher.sweepMisses(audioEngine.currentTime);
 94→        misses.forEach((miss) => {
 95→          recordMiss(miss.step, miss.instrumentId);
 96→        });
 97→      }, 50);
 98→    } else {
 99→      if (sweepIntervalRef.current) {
100→        clearInterval(sweepIntervalRef.current);
101→      }
102→    }
103→
104→    return () => {
105→      if (sweepIntervalRef.current) {
106→        clearInterval(sweepIntervalRef.current);
107→      }
108→    };
109→  }, [isActive, recordMiss]);
110→
111→  // Reset step accuracy display each bar (so colors don't pile up forever)
112→  useEffect(() => {
113→    const unsubscribe = scheduler.addStepListener((step) => {
114→      if (step === 0 && useLivePracticeStore.getState().isActive) {
115→        useLivePracticeStore.getState().resetStepAccuracies();
116→      }
117→    });
118→    return unsubscribe;
119→  }, []);
120→
121→  // Handle keyboard taps
122→  useLiveKeyboardHandler(tapMatcherRef.current, isActive);
123→
124→  // Handle play/stop with session tracking
125→  const handlePlay = useCallback(() => {
126→    tapMatcherRef.current?.reset();
127→    sessionStartRef.current = Date.now();
128→    startSession();
129→    resetStepAccuracies();
130→    play();
131→  }, [play, startSession, resetStepAccuracies]);
132→
133→  const handleStop = useCallback(() => {
134→    const sessionEndTime = Date.now();
135→    stop();
136→    // Final sweep for any remaining expected beats
137→    if (tapMatcherRef.current) {
138→      const misses = tapMatcherRef.current.sweepMisses(Infinity);
139→      const rm = useLivePracticeStore.getState().recordMiss;
140→      misses.forEach((miss) => rm(miss.step, miss.instrumentId));
141→    }
142→    endSession();
143→
144→    // Persist session to history
145→    const finalStats = useLivePracticeStore.getState().stats;
146→    const currentPattern = usePatternStore.getState().currentPattern;
147→    const currentBpm = useTransportStore.getState().bpm;
148→    const durationMs = sessionEndTime - sessionStartRef.current;
149→
150→    if (finalStats.totalExpected > 0 && durationMs > 5000) {
151→      const accuracy = Math.round(
152→        (finalStats.totalHits / finalStats.totalExpected) * 100
153→      );
154→      addHistorySession({
155→        patternId: currentPattern.id,
156→        patternName: currentPattern.name,
157→        mode: 'live',
158→        startedAt: sessionStartRef.current,
159→        endedAt: sessionEndTime,
160→        durationMs,
161→        bpm: currentBpm,
162→        accuracy,
163→        stats: { ...finalStats },
164→      });
165→      updateCard(currentPattern.id, accuracy);
166→      setShowResults(true);
167→    }
168→  }, [stop, endSession, addHistorySession, updateCard]);
169→
170→  const handleRetry = useCallback(() => {
171→    setShowResults(false);
172→    handlePlay();
173→  }, [handlePlay]);
174→
175→  const router = useRouter();
176→  const handleBackToPatterns = useCallback(() => {
177→    setShowResults(false);
178→    router.push('/');
179→  }, [router]);
180→
