  1→import { create } from 'zustand';
  2→import { InstrumentId } from '../patterns/types';
  3→import {
  4→  LiveMode,
  5→  TapEvent,
  6→  TimingGrade,
  7→  SessionStats,
  8→  StepAccuracy,
  9→  KeyMapping,
 10→  DEFAULT_KEY_MAPPINGS,
 11→} from '../live-practice/types';
 12→
 13→function emptyStats(): SessionStats {
 14→  return {
 15→    totalExpected: 0,
 16→    totalHits: 0,
 17→    totalMisses: 0,
 18→    perfectCount: 0,
 19→    greatCount: 0,
 20→    goodCount: 0,
 21→    earlyLateCount: 0,
 22→    averageOffset: 0,
 23→    currentStreak: 0,
 24→    bestStreak: 0,
 25→  };
 26→}
 27→
 28→function isHit(grade: TimingGrade): boolean {
 29→  return grade === 'perfect' || grade === 'great' || grade === 'good';
 30→}
 31→
 32→interface LivePracticeStore {
 33→  mode: LiveMode;
 34→  focusedTrack: InstrumentId | null;
 35→  isActive: boolean;
 36→
 37→  stepAccuracies: Record<string, StepAccuracy>;
 38→  lastTapGrade: TimingGrade | null;
 39→  lastTapInstrument: InstrumentId | null;
 40→
 41→  stats: SessionStats;
 42→  keyMappings: KeyMapping[];
 43→
 44→  setMode: (mode: LiveMode) => void;
 45→  setFocusedTrack: (instrument: InstrumentId | null) => void;
 46→  startSession: () => void;
 47→  endSession: () => void;
 48→  recordTap: (tap: TapEvent) => void;
 49→  recordMiss: (step: number, instrumentId: InstrumentId) => void;
 50→  setStepAccuracy: (step: number, instrumentId: InstrumentId, grade: TimingGrade, offset: number) => void;
 51→  resetStepAccuracies: () => void;
 52→}
 53→
 54→export const useLivePracticeStore = create<LivePracticeStore>((set, get) => ({
 55→  mode: 'full-kit',
 56→  focusedTrack: null,
 57→  isActive: false,
 58→
 59→  stepAccuracies: {},
 60→  lastTapGrade: null,
 61→  lastTapInstrument: null,
 62→
 63→  stats: emptyStats(),
 64→  keyMappings: DEFAULT_KEY_MAPPINGS,
 65→
 66→  setMode: (mode: LiveMode) => set({ mode }),
 67→
 68→  setFocusedTrack: (instrument: InstrumentId | null) => set({ focusedTrack: instrument }),
 69→
 70→  startSession: () =>
 71→    set({
 72→      isActive: true,
 73→      stats: emptyStats(),
 74→      stepAccuracies: {},
 75→      lastTapGrade: null,
 76→      lastTapInstrument: null,
 77→    }),
 78→
 79→  endSession: () => set({ isActive: false }),
 80→
 81→  recordTap: (tap: TapEvent) => {
 82→    const stats = { ...get().stats };
 83→
 84→    if (tap.matchedStep !== null) {
 85→      stats.totalExpected++; // count toward expected since it was matched
 86→      if (isHit(tap.grade)) {
 87→        stats.totalHits++;
 88→        stats.currentStreak++;
 89→        if (stats.currentStreak > stats.bestStreak) {
 90→          stats.bestStreak = stats.currentStreak;
 91→        }
 92→      } else {
 93→        stats.earlyLateCount++;
 94→        stats.currentStreak = 0;
 95→      }
 96→
 97→      switch (tap.grade) {
 98→        case 'perfect': stats.perfectCount++; break;
 99→        case 'great': stats.greatCount++; break;
100→        case 'good': stats.goodCount++; break;
101→      }
102→
103→      // Incremental average offset
104→      const total = stats.totalHits + stats.earlyLateCount;
105→      if (total > 0) {
106→        stats.averageOffset =
107→          ((stats.averageOffset * (total - 1)) + tap.offset) / total;
108→      }
109→    }
110→
111→    set({
112→      stats,
113→      lastTapGrade: tap.grade,
114→      lastTapInstrument: tap.instrumentId,
115→    });
116→  },
117→
118→  recordMiss: (step: number, instrumentId: InstrumentId) => {
119→    const stats = { ...get().stats };
120→    stats.totalExpected++;
121→    stats.totalMisses++;
122→    stats.currentStreak = 0;
123→
124→    const key = `${step}-${instrumentId}`;
125→    const accuracies = { ...get().stepAccuracies };
126→    accuracies[key] = { step, instrumentId, grade: 'miss', offset: 0 };
127→
128→    set({ stats, stepAccuracies: accuracies });
129→  },
130→
131→  setStepAccuracy: (step: number, instrumentId: InstrumentId, grade: TimingGrade, offset: number) => {
132→    const key = `${step}-${instrumentId}`;
133→    const accuracies = { ...get().stepAccuracies };
134→    accuracies[key] = { step, instrumentId, grade, offset };
135→    set({ stepAccuracies: accuracies });
136→  },
137→
138→  resetStepAccuracies: () => set({ stepAccuracies: {} }),
139→}));
