102→export function getDuePatterns(): string[] {
103→  const { cards } = usePracticeHistoryStore.getState();
104→
105→  // Patterns with cards that are due
106→  const due = Object.values(cards)
107→    .filter(isCardDue)
108→    .sort((a, b) => {
109→      if (a.nextReviewAt === null) return 1;
110→      if (b.nextReviewAt === null) return -1;
111→      return a.nextReviewAt - b.nextReviewAt;
112→    })
113→    .map((card) => card.patternId);
114→
115→  // Patterns never practiced in live mode
116→  const practiced = new Set(Object.keys(cards));
117→  const neverPracticed = allPatterns
118→    .filter((p) => !practiced.has(p.id))
119→    .map((p) => p.id);
120→
121→  return [...due, ...neverPracticed];
122→}
