import { InstrumentId } from '../patterns/types';

export const TIMING_THRESHOLDS = {
  PERFECT: 0.015,
  GREAT: 0.030,
  GOOD: 0.050,
  MAX_WINDOW: 0.100,
} as const;

export type TimingGrade = 'perfect' | 'great' | 'good' | 'early' | 'late' | 'miss';

export type LiveMode = 'full-kit' | 'single-track';

export interface ExpectedBeat {
  step: number;
  time: number;
  instrumentId: InstrumentId;
  matched: boolean;
}

export interface TapEvent {
  timestamp: number;
  instrumentId: InstrumentId;
  matchedStep: number | null;
  offset: number;
  grade: TimingGrade;
}

export interface StepAccuracy {
  step: number;
  instrumentId: InstrumentId;
  grade: TimingGrade;
  offset: number;
}

export interface SessionStats {
  totalExpected: number;
  totalHits: number;
  totalMisses: number;
  perfectCount: number;
  greatCount: number;
  goodCount: number;
  earlyLateCount: number;
  averageOffset: number;
  currentStreak: number;
  bestStreak: number;
}

